INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a9ceac7493ff48c61b37','Cardiology amedex 2025.pdf','87','Cardiology','Which one of the following is not associated with prolongation of QT interval?','{"A":"A. Hypothyroidism.","B":"OB. Hypercalcemia.","C":"C. Haloperidol.","D":"D. Sotalol.","E":"E. Methadone."}','B','The following is a list of conditions that can cause QT prolongation:

¢ Hereditary syndromes (rare)

¢ Electrolyte/metabolic abnormalities including hypocalcemia, hypokalemia or hypomagnesemia
e Intrinsic cardiac disease

e Medications:

© Antiarrhythmics: amiodarone, disopyramide, dofetilide, ibutilide, procainamide, quinidine,
sotalol

°o Antihistamines: astemizole, terfenadine

© Antibiotics: clarythromycin, erythromycin, pentamidine, sparfloxacin

°o Anti-malarials: chloroquine, halofantrine

© Anti-psychotics: chlorpromazine, haloperidole, mesoridazine, pimozide, thioridazine

© Gastrointestinal drugs: cisapride, domperidone

© Opiate agonists: methadone, levomethadyl

© Other: Arsenic trioxide, bepridil, droperidol, probucol

e CNS disorders
e Systemic illnesses
¢ Myocardial Infarction

Hypercalcemia is associated with shortening of QT interval and does not cause QT interval prolongation.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[87],"source_qid":null,"duplicate_group_id":"exact-e546a8ccf312","duplicate_sources":[{"record_id":"a9ceac7493ff48c61b37","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":87,"source_qid":null},{"record_id":"34b25f624da183c3754c","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":65,"source_qid":null},{"record_id":"5818ee2617da01ae48f7","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":64,"source_qid":null},{"record_id":"e8fca0c141b1470022c8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":41,"source_qid":"250"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"a9ceac7493ff48c61b37","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":87,"supporting_pages":[87],"source_qid":null,"domain_hint":"Cardiology","stem":"Which one of the following is not associated with prolongation of QT interval?","options":{"A":"A. Hypothyroidism.","B":"OB. Hypercalcemia.","C":"C. Haloperidol.","D":"D. Sotalol.","E":"E. Methadone."},"source_answer":"B","source_explanation":"The following is a list of conditions that can cause QT prolongation:\n\n¢ Hereditary syndromes (rare)\n\n¢ Electrolyte/metabolic abnormalities including hypocalcemia, hypokalemia or hypomagnesemia\ne Intrinsic cardiac disease\n\ne Medications:\n\n© Antiarrhythmics: amiodarone, disopyramide, dofetilide, ibutilide, procainamide, quinidine,\nsotalol\n\n°o Antihistamines: astemizole, terfenadine\n\n© Antibiotics: clarythromycin, erythromycin, pentamidine, sparfloxacin\n\n°o Anti-malarials: chloroquine, halofantrine\n\n© Anti-psychotics: chlorpromazine, haloperidole, mesoridazine, pimozide, thioridazine\n\n© Gastrointestinal drugs: cisapride, domperidone\n\n© Opiate agonists: methadone, levomethadyl\n\n© Other: Arsenic trioxide, bepridil, droperidol, probucol\n\ne CNS disorders\ne Systemic illnesses\n¢ Myocardial Infarction\n\nHypercalcemia is associated with shortening of QT interval and does not cause QT interval prolongation.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["antibiotic","drug","interval"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"e546a8ccf312fc91341b6439aa40099c0272f253","duplicate_group_id":"exact-e546a8ccf312","duplicate_sources":[{"record_id":"a9ceac7493ff48c61b37","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":87,"source_qid":null},{"record_id":"34b25f624da183c3754c","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":65,"source_qid":null},{"record_id":"5818ee2617da01ae48f7","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":64