INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('51a887c5cbe7f16c8938','Cardiology amedex 2025.pdf','89','Cardiology','A 76-year-old man comes to your office for evaluation. He mentions that he has difficulty walking because of the
left leg pain. The pain is brought on after walking two blocks and gets better when he stops to rest. On
examination, the leg skin is shiny and dark. The leg''s hair is lost and the muscles are atrophied. Distal pulses are
difficult to palpate. Which one of the following is the most likely diagnosis?','{"A":"A. Acute limb ischemia.","B":"B. Deep vein thrombosis.","C":"C. Superficial vein thrombosis.","D":"OD. Chronic obstructive arterial disease.","E":"E. Spinal canal stenosis."}','D','Leg pain brought up by walking and relieved by rest and weak or absent distal pulses are characteristic of chronic
limb ischemias as a result of chronic obstructive arterial disease. Atrophied muscles and shiny hairless skin
supports the diagnosis.

The clinical findings in chronic limb ischemia include:

e Weak or absent distal pulses — the hallmark finding
e Shiny and hyperpigmented skin

¢ Hairloss and leg ulcers

e Thickened nails

¢ Muscular atrophy

e Vascular bruits

(Option A) Acute limb ischemia presents with sudden onset pain, pallor, paralysis, paresthesia, pulselessness,
and poikilothermia. This patient has features of chronic limb ischemia.

(Option B) Leg pain due to deep vein thrombosis can be brought on by walking and relieved by rest (similar to
chronic limb ischemia), but other features such as sparse leg hair, pigmentation, muscle atrophy, etc are not
features of DVT. DVT presents with leg pain and tenderness, swelling, and warmth.

(Option C) Superficial thrombophlebitis presents with pain, erythema, induration, and tenderness along the course
of a superficial vein.

(Option E) Leg pain caused by neurogenic claudication due to spinal canal stenosis tends to get worse with erect
posture and is relieved by recumbency. The absence of neurological deficits makes this diagnosis less likely.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[89],"source_qid":null,"duplicate_group_id":"exact-7c41cc03ef8c","duplicate_sources":[{"record_id":"51a887c5cbe7f16c8938","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":89,"source_qid":null},{"record_id":"f55d9b19a6e124feb4a4","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":7,"source_qid":null},{"record_id":"58e01c27e005f5fc59ec","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":59,"source_qid":"270"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"51a887c5cbe7f16c8938","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":89,"supporting_pages":[89],"source_qid":null,"domain_hint":"Cardiology","stem":"A 76-year-old man comes to your office for evaluation. He mentions that he has difficulty walking because of the\nleft leg pain. The pain is brought on after walking two blocks and gets better when he stops to rest. On\nexamination, the leg skin is shiny and dark. The leg''s hair is lost and the muscles are atrophied. Distal pulses are\ndifficult to palpate. Which one of the following is the most likely diagnosis?","options":{"A":"A. Acute limb ischemia.","B":"B. Deep vein thrombosis.","C":"C. Superficial vein thrombosis.","D":"OD. Chronic obstructive arterial disease.","E":"E. Spinal canal stenosis."},"source_answer":"D","source_explanation":"Leg pain brought up by walking and relieved by rest and weak or absent distal pulses are characteristic of chronic\nlimb ischemias as a result of chronic obstructive arterial disease. Atrophied muscles and shiny hairless skin\nsupports the diagnosis.\n\nThe clinical findings in chronic limb ischemia include:\n\ne Weak or absent distal pulses — the hallmark finding\ne Shiny and hyperpigmented skin\n\n¢ Hairloss and leg ulcers\n\ne Thickened nails\n\n¢ Muscular atrophy\n\ne Vascular bruits\n\n(Option A) Acute limb ischemia presents with sudden onset pain, pallor, paralysis, paresthesia, pulselessness,\nand poikilothermia. This patient has features of chronic limb ischemia.\n\n(Option B) Leg pain due to deep vein thrombosis can be brought on by walking and relieved by rest (similar to\nchronic limb ischemia), but other features such as sparse leg hair, pigmentation, muscle atrophy, etc are not\nfeatures of DVT. DVT presents with leg pain and tenderness, swelling, and warmth.\n\n(Option C) Superficial thrombophlebitis presents with pain, erythema, induration, and tenderness along the course\nof a superficial vein.\n\n(Option E) Leg pain caused by neurogenic claudication due to spinal canal stenosis tends to get worse with erect\nposture and is relieved by recumbency. The absence of neurological deficits makes this diagnosis less likely.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["duration"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"7c41cc03ef8cf6e8b3af1db1909112bbe55433ca","duplicate_group_id":"exact-7c41cc03ef8c","duplicate_sources":[{"record_id":"51a887c5cbe7f16c8938","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":89,"source_qid":null},{"record_id":"f55d9b19a6e124feb4a4","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":7,"source_qid":null},{"record_id":"58e01c27e005f5fc59ec","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":59,"source_qid":"270"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
