INSERT INTO sources (id,name,source_type,source_year,drive_locator,copyright_scope,import_status,current_guideline_status,metadata_json) VALUES ('src-v294-eaee30a7','Cardiology amedex 2025.pdf','AMC question-bank source','2025','AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf','private-study','v2.9.4-imported','needs-verification','{"import_version":"v2.9.4"}') ON CONFLICT(id) DO UPDATE SET name=excluded.name,source_year=excluded.source_year,import_status=excluded.import_status,current_guideline_status=excluded.current_guideline_status,metadata_json=excluded.metadata_json;
