INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f66360ff8705b3ba0240','Cardiology amedex 2025.pdf','94','Cardiology','A 67-year-old woman presents to your practice with complaint of dyspnea, especially on exertion.
On heart auscultation, there is a systolic murmur heard over the apex, and a diastolic murmur in
the left upper sternal border. The pulmonary component of S2 is split. Which one of the following is
the most likely diagnosis?','{"A":"OA. Aortic valve stenosis.","B":"B. Mitral valve regurgitation.","C":"C. Pulmonary valve stenosis.","D":"D. Tricuspid valve incompetence.","E":"E. Mitral valve stenosis."}','A','Typically, a split S2 is characteristic of either mitral valve regurgitation (MR) or aortic valve stenosis
(AS) (may be seen in other cardiac conditions such as bundle branch block as well). The murmur
of mitral regurgitation occurs during systole when the mitral valve fails to completely close and
there is blood flow turbulence around the valve.

The typical murmur of the AS is an early systolic harsh murmur best heard over the right upper
sternal border (in the second intercostal space) that can radiate to one or both carotid areas.
However, in elderly patient the murmur may be best heard over the apex and resembles murmurs
caused by MR.

On the other hand, calcified stenotic leaflets of the aortic valve may fail to tightly close during the
diastole and give rise to valve regurgitation and a diastolic murmur.

With the history of exertional dyspnea, and the above mentioned murmurs and more importantly
the split S2, AS will be the most likely diagnosis.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[94],"source_qid":null,"duplicate_group_id":"exact-52485f5cd2de","duplicate_sources":[{"record_id":"f66360ff8705b3ba0240","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":94,"source_qid":null},{"record_id":"30461b2489a8ebdbd607","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":83,"source_qid":"388"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"f66360ff8705b3ba0240","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":94,"supporting_pages":[94],"source_qid":null,"domain_hint":"Cardiology","stem":"A 67-year-old woman presents to your practice with complaint of dyspnea, especially on exertion.\nOn heart auscultation, there is a systolic murmur heard over the apex, and a diastolic murmur in\nthe left upper sternal border. The pulmonary component of S2 is split. Which one of the following is\nthe most likely diagnosis?","options":{"A":"OA. Aortic valve stenosis.","B":"B. Mitral valve regurgitation.","C":"C. Pulmonary valve stenosis.","D":"D. Tricuspid valve incompetence.","E":"E. Mitral valve stenosis."},"source_answer":"A","source_explanation":"Typically, a split S2 is characteristic of either mitral valve regurgitation (MR) or aortic valve stenosis\n(AS) (may be seen in other cardiac conditions such as bundle branch block as well). The murmur\nof mitral regurgitation occurs during systole when the mitral valve fails to completely close and\nthere is blood flow turbulence around the valve.\n\nThe typical murmur of the AS is an early systolic harsh murmur best heard over the right upper\nsternal border (in the second intercostal space) that can radiate to one or both carotid areas.\nHowever, in elderly patient the murmur may be best heard over the apex and resembles murmurs\ncaused by MR.\n\nOn the other hand, calcified stenotic leaflets of the aortic valve may fail to tightly close during the\ndiastole and give rise to valve regurgitation and a diastolic murmur.\n\nWith the history of exertional dyspnea, and the above mentioned murmurs and more importantly\nthe split S2, AS will be the most likely diagnosis.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"52485f5cd2de4778ccf5303bd34e155b8572c469","duplicate_group_id":"exact-52485f5cd2de","duplicate_sources":[{"record_id":"f66360ff8705b3ba0240","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":94,"source_qid":null},{"record_id":"30461b2489a8ebdbd607","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":83,"source_qid":"388"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=