INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a99f4d92f771c394133e','Cardiology amedex 2025.pdf','95','Cardiology','An 82-year-old man presents to your office complaining of an ulcer over the medial side of his leg just above the
internal malleolus. He mentions that the wound has been there for the past 6 months, and worsened recently. The
examination confirms the diagnosis a venous ulcer. The ipsilateral ankle-brachial index is 0.7. Which one of the
following is correct regarding the management of this patient?','{"A":"OA. Compression stockings are unsafe for this patient.","B":"B. Prescribe compression stockings and refer him to a vascular surgeon.","C":"C. Give antibiotics and review in two weeks.","D":"D. Check fasting glucose.","E":"E. Check HbA1C."}','A','Venous leg ulcers are the most common chronic wounds seen in general practice. They account for 70-90% of
chronic wounds. They tend to develop over the medial distal leg (just above the internal malleolus), and are usually
painful.

The most important risk factor for developmet of a venous ulcer is previous deep vein thrombosis (DVT) with
consequent damage to venous structure and insufficiency.

Most venous ulcers respond adequately to a conservative management called Bisggard regimen. This regimen
has four components:

. Patient education

. Elevation of the foot
. Elastic compression
. Evaluation

WN =

Elastic compression is considered for very patient unless:

¢ ABI is below 0.8
e The patient is diabetic

In the above situations, compression stocking causes more compromised arterial flow and makes the limb
ischemia worse; therefore, specialist advice and close monitoring is strongly recommended.

Antibiotics are not indicated in uncomplicated venous ulcers. Diabetes is one of the most important predisposing
factors in development of arterial ulcers. Although fasting glucose level may be considered for screening of
diabetes, it is not a step in management here. HbA1C is used to monitor efficacy of or adherence to anti-
hyperglycemic regimens, which is not the case here.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[95],"source_qid":null,"duplicate_group_id":"exact-d53129f8882f","duplicate_sources":[{"record_id":"a99f4d92f771c394133e","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":95,"source_qid":null},{"record_id":"4dfe15cba94b896c211e","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":61,"source_qid":null},{"record_id":"7794f976b1a44f6639ab","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":67,"source_qid":"276"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"a99f4d92f771c394133e","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":95,"supporting_pages":[95],"source_qid":null,"domain_hint":"Cardiology","stem":"An 82-year-old man presents to your office complaining of an ulcer over the medial side of his leg just above the\ninternal malleolus. He mentions that the wound has been there for the past 6 months, and worsened recently. The\nexamination confirms the diagnosis a venous ulcer. The ipsilateral ankle-brachial index is 0.7. Which one of the\nfollowing is correct regarding the management of this patient?","options":{"A":"OA. Compression stockings are unsafe for this patient.","B":"B. Prescribe compression stockings and refer him to a vascular surgeon.","C":"C. Give antibiotics and review in two weeks.","D":"D. Check fasting glucose.","E":"E. Check HbA1C."},"source_answer":"A","source_explanation":"Venous leg ulcers are the most common chronic wounds seen in general practice. They account for 70-90% of\nchronic wounds. They tend to develop over the medial distal leg (just above the internal malleolus), and are usually\npainful.\n\nThe most important risk factor for developmet of a venous ulcer is previous deep vein thrombosis (DVT) with\nconsequent damage to venous structure and insufficiency.\n\nMost venous ulcers respond adequately to a conservative management called Bisggard regimen. This regimen\nhas four components:\n\n. Patient education\n\n. Elevation of the foot\n. Elastic compression\n. Evaluation\n\nWN =\n\nElastic compression is considered for very patient unless:\n\n¢ ABI is below 0.8\ne The patient is diabetic\n\nIn the above situations, compression stocking causes more compromised arterial flow and makes the limb\nischemia worse; therefore, specialist advice and close monitoring is strongly recommended.\n\nAntibiotics are not indicated in uncomplicated venous ulcers. Diabetes is one of the most important predisposing\nfactors in development of arterial ulcers. Although fasting glucose level may be considered for screening of\ndiabetes, it is not a step in management here. HbA1C is used to monitor efficacy of or adherence to anti-\nhyperglycemic regimens, which is not the case here.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","antibiotic","diabetes","management","screen","screening"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"d53129f8882fd78884cb385b580f56c883d5e13a","duplicate_group_id":"exact-d53129f8882f","duplicate_sources":[{"record_id":"a99f4d92f771c394133e","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":95,"source_qid":null},{"record_id":"4dfe15cba94b896c211e","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":61,"source_qid":null},{"record_id":"7794f976b1a44f6639ab","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":67,"source_qid":"276"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
