management?','{"A":"A. Metoprolol.","B":"OB. Dopamine.","C":"OC. Intravenous pacemaker.","D":"D. Permanent pacemaker.","E":"E. Adrenaline."}',NULL,NULL,'{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[98],"source_qid":null,"duplicate_group_id":"exact-cfb834e652c3","duplicate_sources":[{"record_id":"3fda9236b4420b3bf750","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":98,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"3fda9236b4420b3bf750","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":98,"supporting_pages":[98],"source_qid":null,"domain_hint":"Cardiology","stem":"A /0-year-old man in brought to the emergency\ndepartment because of light-headedness for the past\n4 hours. On examination, he is found to have\nbradycardia with an irregular pulse of 45 bpm and a\nblood pressure of 85/60 mmHg. Atropine is used as\nthe treatment of symptomatic bradycardia, but the\npulse rate remains the same, and the\nlightheadedness persists. An ECG strip is obtained\nwhich is shown in the following photograph. Which\none of the following is the next best step in\nmanagement?","options":{"A":"A. Metoprolol.","B":"OB. Dopamine.","C":"OC. Intravenous pacemaker.","D":"D. Permanent pacemaker.","E":"E. Adrenaline."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","treatment"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"cfb834e652c3f290e9637ce03fdf6fd03a4f0b10","duplicate_group_id":"exact-cfb834e652c3","duplicate_sources":[{"record_id":"3fda9236b4420b3bf750","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":98,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
