INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6e97cea7a9d621db586f','Cardiology amedex 2025.pdf','101','Cardiology','A 55-year-old man is on heparin after he developed an acute limb ischemia. Which of the
following tests is used for monitoring the response to anticoagulation therapy with heparin?','{"A":"A. Fibrinogen level.","B":"B. Prothrombin time (PT).","C":"C. INR.","D":"OD. Activated partial thromboplastin time (aPTT).","E":"E. Bleeding time (BT)."}','D','Activated partial thromboplastin time (aPTT) is used to assess the integrity of the following
coagulation pathways:

e The intrinsic pathway that includes prekallikrein, high molecular weight kininogen, and
factors VIII, IX, XI, and XI.
¢ Common pathways include factors Il, V, X, and fibrinogen.

aPTT is also used for monitoring the effects of maintenance therapy with heparin. Usually,
the goal of heparin maintenance therapy is to keep aPTT level 1.5- 2.5 times above the
patient’s aPTT baseline. When starting heparin therapy, aPTT is measured every 6 hours
until it is within the therapeutic range of 65-100 seconds, and every 24 hours afterward.

INR is used for monitoring warfarin therapy. It assesses the extrinsic coagulation pathway,
as does PT. The normal range of PT in an individual not on blood thinners is 11-13.5
seconds. PT and INR are prolonged if the patient is on warfarin, deficient in factors II
(prothrombin), Ill, IX, X, or fibrinogen, or has vitamin K deficiency.

BT is used as a platelet function test with a normal range of 1-9 minutes. It is prolonged if
the patient is on antiplatelet medications (aspirin, clopidogrel), has thrombocytopenia, or in
those with platelet aggregation disorders e.g. Von-Willebrand disease. BT is not used
routinely anymore.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","supporting_pages":[101],"source_qid":null,"duplicate_group_id":"exact-019aa1e223f3","duplicate_sources":[{"record_id":"6e97cea7a9d621db586f","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":101,"source_qid":null},{"record_id":"f601b4ded40363b8db34","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":112,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"6e97cea7a9d621db586f","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_year":2025,"source_page":101,"supporting_pages":[101],"source_qid":null,"domain_hint":"Cardiology","stem":"A 55-year-old man is on heparin after he developed an acute limb ischemia. Which of the\nfollowing tests is used for monitoring the response to anticoagulation therapy with heparin?","options":{"A":"A. Fibrinogen level.","B":"B. Prothrombin time (PT).","C":"C. INR.","D":"OD. Activated partial thromboplastin time (aPTT).","E":"E. Bleeding time (BT)."},"source_answer":"D","source_explanation":"Activated partial thromboplastin time (aPTT) is used to assess the integrity of the following\ncoagulation pathways:\n\ne The intrinsic pathway that includes prekallikrein, high molecular weight kininogen, and\nfactors VIII, IX, XI, and XI.\n¢ Common pathways include factors Il, V, X, and fibrinogen.\n\naPTT is also used for monitoring the effects of maintenance therapy with heparin. Usually,\nthe goal of heparin maintenance therapy is to keep aPTT level 1.5- 2.5 times above the\npatient’s aPTT baseline. When starting heparin therapy, aPTT is measured every 6 hours\nuntil it is within the therapeutic range of 65-100 seconds, and every 24 hours afterward.\n\nINR is used for monitoring warfarin therapy. It assesses the extrinsic coagulation pathway,\nas does PT. The normal range of PT in an individual not on blood thinners is 11-13.5\nseconds. PT and INR are prolonged if the patient is on warfarin, deficient in factors II\n(prothrombin), Ill, IX, X, or fibrinogen, or has vitamin K deficiency.\n\nBT is used as a platelet function test with a normal range of 1-9 minutes. It is prolonged if\nthe patient is on antiplatelet medications (aspirin, clopidogrel), has thrombocytopenia, or in\nthose with platelet aggregation disorders e.g. Von-Willebrand disease. BT is not used\nroutinely anymore.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["anticoag","antiplatelet","therapy","warfarin"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"019aa1e223f334e682bbc98c493bfaa592122d52","duplicate_group_id":"exact-019aa1e223f3","duplicate_sources":[{"record_id":"6e97cea7a9d621db586f","record_type":"text_mcq","source_file":"Cardiology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Cardiology amedex 2025.pdf","source_page":101,"source_qid":null},{"record_id":"f601b4ded40363b8db34","record_type":"text_mcq","source_file":"AMEDEX 2025 CVS (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (1).pdf","source_page":112,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
