INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('dd7ae2d4baa46bbc5dfe','Dermatology amedex 2025.pdf','3','Dermatology','A 61-year-old woman presents to your practice complaining of a rash on her left shin. On examination, there is a well-demarcated 3x2cm
erythematous lesion. It is neither painful, nor itchy. The lesion is shown in the accompanying photograph. Which one of the following is the most
likely diagnosis?',NULL,'E','The large raised scaly plaque shown in the picture has the characteristic features of Bowen’s disease.

Bowen''s disease is squamous Cell carcinoma in situ of the skin. The disease is more commonly seen in those over 60 years of age, but it can be
found at any age (rare before 30 years). Sun exposure is the most significant risk factor.

Bowen''s disease presents as a well-demarcated erythematous and scaling plaque that may be mistaken for psoriasis or dermatitis. It is usually
asymptomatic, but ulceration is a possibility. In 10-20% of cases there are multiple lesions. Although Bowen’s disease can virtually occur
anywhere in the body, the sun-exposed areas, particularly the lower legs are the most common site of presentation.

The diagnosis is confirmed and documented by punch or shave biopsy. All of the following options can be successfully used for treatment with
about the same efficacy and a recurrence rate of 5-10%:

¢ Topical fluorouracil

¢ Imiquimod

¢ Cryotherapy

e Curettage

¢ Cautery

¢ Excision

¢ Photodynamic therapy
e Laser therapy

¢ Radiation therapy

Mohs’ surgery is used when the anatomic location of the lesion is of functional consideration (e.g. penis, fingers) or for cosmetic issues.
Occasionally, observation may be considered if the lesion is progressing slowly and is located in areas with poor healing ability such as the
anterior leg of an old person.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[3],"source_qid":null,"duplicate_group_id":"exact-ac8dede957e7","duplicate_sources":[{"record_id":"dd7ae2d4baa46bbc5dfe","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":3,"source_qid":null},{"record_id":"0282a55c29ff721ef657","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":100,"source_qid":null},{"record_id":"bfa0ca42788507fcb54a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":239,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":"manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00102.jpg","asset_preview_url":"https://drive.google.com/file/d/11lasd45oB7diVNqldFztszkac-8g8VHd/preview"}','manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00102.jpg','https://drive.google.com/thumbnail?id=11lasd45oB7diVNqldFztszkac-8g8VHd&sz=w1600',NULL,NULL,'needs_verification','[]','high','{"record_id":"dd7ae2d4baa46bbc5dfe","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":3,"supporting_pages":[3],"source_qid":null,"domain_hint":"Dermatology","stem":"A 61-year-old woman presents to your practice complaining of a rash on her left shin. On examination, there is a well-demarcated 3x2cm\nerythematous lesion. It is neither painful, nor itchy. The lesion is shown in the accompanying photograph. Which one of the following is the most\nlikely diagnosis?","options":{},"source_answer":"E","source_explanation":"The large raised scaly plaque shown in the picture has the characteristic features of Bowen’s disease.\n\nBowen''s disease is squamous Cell carcinoma in situ of the skin. The disease is more commonly seen in those over 60 years of age, but it can be\nfound at any age (rare before 30 years). Sun exposure is the most significant risk factor.\n\nBowen''s disease presents as a well-demarcated erythematous and scaling plaque that may be mistaken for psoriasis or dermatitis. It is usually\nasymptomatic, but ulceration is a possibility. In 10-20% of cases there are multiple lesions. Although Bowen’s disease can virtually occur\nanywhere in the body, the sun-exposed areas, particularly the lower legs are the most common site of presentation.\n\nThe diagnosis is confirmed and documented by punch or shave biopsy. All of the following options can be successfully used for treatment with\nabout the same efficacy and a recurrence rate of 5-10%:\n\n¢ Topical fluorouracil\n\n¢ Imiquimod\n\n¢ Cryotherapy\n\ne Curettage\n\n¢ Cautery\n\n¢ Excision\n\n¢ Photodynamic therapy\ne Laser therapy\n\n¢ Radiation therapy\n\nMohs’ surgery is used when the anatomic location of the lesion is of functional consideration (e.g. penis, fingers) or for cosmetic issues.\nOccasionally, observation may be considered if the lesion is progressing slowly and is located in areas with poor healing ability such as the\nanterior leg of an old person.","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","therapy","treatment"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ac8dede957e7c24dbeb4b4b8627c7033aad33aba","duplicate_group_id":"exact-ac8dede957e7","duplicate_sources":[{"record_id":"dd7ae2d4baa46bbc5dfe","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":3,"source_qid":null},{"record_id":"0282a55c29ff721ef657","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":100,"source_qid":null},{"record_id":"bfa0ca42788507fcb54a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":239,"source_qid":null}],"visual_assets":["manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00102.jpg"],"visual_asset":"manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00102.jpg"}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
