INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3990f2689383a5d80dbb','Dermatology amedex 2025.pdf','5','Dermatology','A 43-year-old farmer from Queensland presents with a pigmented lesion on his upper chest, shown in the accompanying photograph. The lesion
appeared 4 months ago, but recently has enlarged. The lesion has been itchy and oozing and painful for the past 3 weeks. Which one of the
following is the most likely diagnosis?',NULL,'A','Although the lesion shown in the photograph may be mistakenly considered as a pigmented nodular basal cell carcinoma, a more careful

inspection of the lesion indicating pigmentation of different colors as well as the history of the rapid progression over 4 months suggests malignant
melanoma (nodular type) as the most likely diagnosis.

(Option B) Keratoacanthoma has the typical crater which is absent here. The crater often has keratin or dead skin cells inside.

Keratoacanthoma - note the nodular structure and the presence of a crater

(Option C) Pigmentation and color variegation of this lesion favors melanoma rather than basal cell carcinoma. Moreover, the rapid progression
and evolution of symptoms such as itching and tenderness are more commonly seen in melanoma.

(Options D and E) Clinical presentation and the history (rapid course of progression and evolving of size and symptoms) definitely exclude blue
nevus and benign pigmentation as the likely diagnoses.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[5],"source_qid":null,"duplicate_group_id":"exact-05c11e32c050","duplicate_sources":[{"record_id":"3990f2689383a5d80dbb","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":5,"source_qid":null},{"record_id":"a4a3db366a192c718201","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":154,"source_qid":null},{"record_id":"cf4bb067e7d5ae6f137b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":249,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":"manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00156.jpg","asset_preview_url":"https://drive.google.com/file/d/10qqVxB7XfhkaRurYdOe9hTF_wKAakcdY/preview"}','manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00156.jpg','https://drive.google.com/thumbnail?id=10qqVxB7XfhkaRurYdOe9hTF_wKAakcdY&sz=w1600',NULL,NULL,'needs_verification','[]','low','{"record_id":"3990f2689383a5d80dbb","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":5,"supporting_pages":[5],"source_qid":null,"domain_hint":"Dermatology","stem":"A 43-year-old farmer from Queensland presents with a pigmented lesion on his upper chest, shown in the accompanying photograph. The lesion\nappeared 4 months ago, but recently has enlarged. The lesion has been itchy and oozing and painful for the past 3 weeks. Which one of the\nfollowing is the most likely diagnosis?","options":{},"source_answer":"A","source_explanation":"Although the lesion shown in the photograph may be mistakenly considered as a pigmented nodular basal cell carcinoma, a more careful\n\ninspection of the lesion indicating pigmentation of different colors as well as the history of the rapid progression over 4 months suggests malignant\nmelanoma (nodular type) as the most likely diagnosis.\n\n(Option B) Keratoacanthoma has the typical crater which is absent here. The crater often has keratin or dead skin cells inside.\n\nKeratoacanthoma - note the nodular structure and the presence of a crater\n\n(Option C) Pigmentation and color variegation of this lesion favors melanoma rather than basal cell carcinoma. Moreover, the rapid progression\nand evolution of symptoms such as itching and tenderness are more commonly seen in melanoma.\n\n(Options D and E) Clinical presentation and the history (rapid course of progression and evolving of size and symptoms) definitely exclude blue\nnevus and benign pigmentation as the likely diagnoses.","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"05c11e32c05011fcac9d9cb7aab645a3d4bcc337","duplicate_group_id":"exact-05c11e32c050","duplicate_sources":[{"record_id":"3990f2689383a5d80dbb","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":5,"source_qid":null},{"record_id":"a4a3db366a192c718201","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":154,"source_qid":null},{"record_id":"cf4bb067e7d5ae6f137b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":249,"source_qid":null}],"visual_assets":["manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00156.jpg"],"visual_asset":"manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00156.jpg"}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
