INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1387f4805d35db1cb764','Dermatology amedex 2025.pdf','8','Dermatology','A 59-year-old farmer presents to your clinic with a lesion on his upper chest. The lesion has appeared and
progressively enlarged in the past 2 months. Examination establishes a diagnosis keratoacanthoma with
high certainty. Keratoacanthoma is more likely to be confused with which one of the following?','{"A":"Basal cell carcinoma.","B":"OB. Squamous cell carcinoma.","C":"Pyogenic granuloma.","D":"Seborrheic keratosis.","E":"Granuloma fissuratum."}','B','Keratoacanthoma (KA) is a rapidly growing tumor of keratinocytes. They are almost exclusively seen in sun-
exposed areas. The characteristic feature is the crater; the central part of the lesion is necrotic, giving the
lesion the appearance of a volcano.

KAs are now considered a low-risk variant of squamous cell carcinoma (SCC). The major diagnostic problem
is confusion with SCC, especailly for KAs of the nose and the lips. Interestingly, sometimes KAs cannot be
told apart from SCCs based on cytological studies and the whole specimen is needed for differentiation.

(Option A) An ulcerated nodular BCC may resemble KA, but SCC remains the most confusing differential
diagnosis.

(Options C and D) Pyogenic granuloma and seborrheic keratosis are very unlikely to be confused with KA.

(Option E) Granuloma fissuratum is a firm red fissured fibrotic granuloma found in the gums and buccal
mucosa. It is usually caused by ill-fitting dentures.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-018e6d2672ba","duplicate_sources":[{"record_id":"1387f4805d35db1cb764","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":8,"source_qid":null},{"record_id":"45a029ce4051142c83b4","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":190,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"1387f4805d35db1cb764","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":8,"source_qid":null,"domain_hint":"Dermatology","stem":"A 59-year-old farmer presents to your clinic with a lesion on his upper chest. The lesion has appeared and\nprogressively enlarged in the past 2 months. Examination establishes a diagnosis keratoacanthoma with\nhigh certainty. Keratoacanthoma is more likely to be confused with which one of the following?","options":{"A":"Basal cell carcinoma.","B":"OB. Squamous cell carcinoma.","C":"Pyogenic granuloma.","D":"Seborrheic keratosis.","E":"Granuloma fissuratum."},"source_answer":"B","source_explanation":"Keratoacanthoma (KA) is a rapidly growing tumor of keratinocytes. They are almost exclusively seen in sun-\nexposed areas. The characteristic feature is the crater; the central part of the lesion is necrotic, giving the\nlesion the appearance of a volcano.\n\nKAs are now considered a low-risk variant of squamous cell carcinoma (SCC). The major diagnostic problem\nis confusion with SCC, especailly for KAs of the nose and the lips. Interestingly, sometimes KAs cannot be\ntold apart from SCCs based on cytological studies and the whole specimen is needed for differentiation.\n\n(Option A) An ulcerated nodular BCC may resemble KA, but SCC remains the most confusing differential\ndiagnosis.\n\n(Options C and D) Pyogenic granuloma and seborrheic keratosis are very unlikely to be confused with KA.\n\n(Option E) Granuloma fissuratum is a firm red fissured fibrotic granuloma found in the gums and buccal\nmucosa. It is usually caused by ill-fitting dentures.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"018e6d2672bac09c896cbc105154ac21e03e8b5e","duplicate_group_id":"exact-018e6d2672ba","duplicate_sources":[{"record_id":"1387f4805d35db1cb764","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":8,"source_qid":null},{"record_id":"45a029ce4051142c83b4","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":190,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded