INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c37e7ef846a892225fa4','Dermatology amedex 2025.pdf','10','Dermatology','A 47-year-old man presents because of a lesion on the back of his right shoulder. The lesion is illustrated in
the following photograph. Which one of the following is the most appropriate advice?','{"A":"A. The lesion should be excised, as it is malignant and can extend locally, but not through lymph\nnodes.","B":"OB. The lesion is benign and does not need to be excised.","C":"C. The lesion is benign, but should be excised because it can become malignant.","D":"D. The lesion is benign, but should be excised because it can become infected.","E":"E. The lesion is malignant and should be excised because it can metastasize through adjacent lymph\nnodes."}','B','The photograph shows a well-circumscribed lesion that appears to arise from within the epidermis. It also
has a punctum in the centre. These features are characteristic of an epidermoid (sebaceous) cyst,

aka epidermal inclusion cyst. Of note, the yellow cheesy material within the cyst is desquamated keratin, not
sebum.

Epidermoid cysts are the most common cutaneous cysts. While they may occur anywhere on the body, they
occur most frequently on the face, scalp, neck, and trunk.

Epidermoid cysts are benign lesions; however, very rare cases of various associated malignancies have
been reported, but in general and for practical purposes, they do not turn into malignancies.

Asymptomatic epidermoid cysts do not need to be treated. If they become inflamed, intralesional injection
with triamcinolone may hasten the resolution of inflammation. Oral antibiotics may occasionally be indicated.

If surgical treatment is planned, the cyst and cyst wall may be removed via simple excision or incision

through the surgical defect. If the entire cyst wall is not removed, the lesion may recur.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[10],"source_qid":null,"duplicate_group_id":"exact-ce199dbccca1","duplicate_sources":[{"record_id":"c37e7ef846a892225fa4","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":10,"source_qid":null},{"record_id":"29064b56175a1ce209b5","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":303,"source_qid":null},{"record_id":"695eaa27f4e15845db6c","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":193,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"c37e7ef846a892225fa4","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":10,"supporting_pages":[10],"source_qid":null,"domain_hint":"Dermatology","stem":"A 47-year-old man presents because of a lesion on the back of his right shoulder. The lesion is illustrated in\nthe following photograph. Which one of the following is the most appropriate advice?","options":{"A":"A. The lesion should be excised, as it is malignant and can extend locally, but not through lymph\nnodes.","B":"OB. The lesion is benign and does not need to be excised.","C":"C. The lesion is benign, but should be excised because it can become malignant.","D":"D. The lesion is benign, but should be excised because it can become infected.","E":"E. The lesion is malignant and should be excised because it can metastasize through adjacent lymph\nnodes."},"source_answer":"B","source_explanation":"The photograph shows a well-circumscribed lesion that appears to arise from within the epidermis. It also\nhas a punctum in the centre. These features are characteristic of an epidermoid (sebaceous) cyst,\n\naka epidermal inclusion cyst. Of note, the yellow cheesy material within the cyst is desquamated keratin, not\nsebum.\n\nEpidermoid cysts are the most common cutaneous cysts. While they may occur anywhere on the body, they\noccur most frequently on the face, scalp, neck, and trunk.\n\nEpidermoid cysts are benign lesions; however, very rare cases of various associated malignancies have\nbeen reported, but in general and for practical purposes, they do not turn into malignancies.\n\nAsymptomatic epidermoid cysts do not need to be treated. If they become inflamed, intralesional injection\nwith triamcinolone may hasten the resolution of inflammation. Oral antibiotics may occasionally be indicated.\n\nIf surgical treatment is planned, the cyst and cyst wall may be removed via simple excision or incision\n\nthrough the surgical defect. If the entire cyst wall is not removed, the lesion may recur.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["antibiotic","treatment"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ce199dbccca199ab342504f3782bab8f19bdd9ff","duplicate_group_id":"exact-ce199dbccca1","duplicate_sources":[{"record_id":"c37e7ef846a892225fa4","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":10,"source_qid":null},{"record_id":"29064b56175a1ce209b5","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":303,"source_qid":null},{"record_id":"695eaa27f4e15845db6c","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":193,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
