INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('69934d6a971c66955479','Dermatology amedex 2025.pdf','12','Dermatology','A 50-year old farmer presents to your practice with a dark mole on his left cheek. The mole
has been there for 20 years, but has enlarged and become slightly lumpy and itchy over the
past 4 months. Which one of the following would be the most appropriate management option
for this patient?','{"A":"A. Treat the lesion using liquid nitrogen.","B":"B. Ask the patient to return for review in 3 months.","C":"C. Remove the lesion using the laser.","D":"D. Use topical imiquimod for 6 weeks.","E":"OE. Excisional biopsy of the lesion for histopathology."}','E','Achanging mole, a mole with an irregular border, bleeding, itching, or color variegation is
melanoma until proven otherwise. When melanoma is suspected, the next best step is an
excisional biopsy of the lesion with 2 mm margins. Elliptical incisions are made so that
reconstruction of the wound is more straightforward. If histopathological results confirm the
diagnosis, referral to a plastic surgeon is necessary for a wider excision with margins of 5mm
to 3 cm depending on the depth of the lesion.

NOTE - in GP settings, patients with suspected lesions on sensitive areas such as the
head and neck should be referred to a plastic surgeon even for the initial excision. If the
referral was an option, it would be the correct answer.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[12],"source_qid":null,"duplicate_group_id":"exact-7a1c5090df94","duplicate_sources":[{"record_id":"69934d6a971c66955479","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":12,"source_qid":null},{"record_id":"f17b26f834bad88c7e3b","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":86,"source_qid":null},{"record_id":"75d1f3550cbec6b3c943","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":196,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"69934d6a971c66955479","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":12,"supporting_pages":[12],"source_qid":null,"domain_hint":"Dermatology","stem":"A 50-year old farmer presents to your practice with a dark mole on his left cheek. The mole\nhas been there for 20 years, but has enlarged and become slightly lumpy and itchy over the\npast 4 months. Which one of the following would be the most appropriate management option\nfor this patient?","options":{"A":"A. Treat the lesion using liquid nitrogen.","B":"B. Ask the patient to return for review in 3 months.","C":"C. Remove the lesion using the laser.","D":"D. Use topical imiquimod for 6 weeks.","E":"OE. Excisional biopsy of the lesion for histopathology."},"source_answer":"E","source_explanation":"Achanging mole, a mole with an irregular border, bleeding, itching, or color variegation is\nmelanoma until proven otherwise. When melanoma is suspected, the next best step is an\nexcisional biopsy of the lesion with 2 mm margins. Elliptical incisions are made so that\nreconstruction of the wound is more straightforward. If histopathological results confirm the\ndiagnosis, referral to a plastic surgeon is necessary for a wider excision with margins of 5mm\nto 3 cm depending on the depth of the lesion.\n\nNOTE - in GP settings, patients with suspected lesions on sensitive areas such as the\nhead and neck should be referred to a plastic surgeon even for the initial excision. If the\nreferral was an option, it would be the correct answer.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"7a1c5090df94ba761fe1f33e0a3fe082a5d4bed5","duplicate_group_id":"exact-7a1c5090df94","duplicate_sources":[{"record_id":"69934d6a971c66955479","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":12,"source_qid":null},{"record_id":"f17b26f834bad88c7e3b","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":86,"source_qid":null},{"record_id":"75d1f3550cbec6b3c943","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":196,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00