source_qid":null},{"record_id":"57feab10f98730ef521f","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":279,"source_qid":null},{"record_id":"6a4eeed27f65e9d8856f","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":280,"source_qid":null},{"record_id":"5bd84f7dcb7b58c6f16b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":215,"source_qid":"632"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
