INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7d52b1f867d4c451d2c1','Dermatology amedex 2025.pdf','15','Dermatology','John, 60 years of age, presents to your office because he is concerned about a skin lesion on his forearm. The dermatoscopic view of the lesion is
shown in the following photograph. Which one of the following could be the most likely diagnosis?',NULL,'E','The photograph shows an oval brown plaque on a sun-exposed area in an old man. There is also keratotic plugging in the surface of the lesion
(yellowish-colored). These features are characteristic of seborrheic keratosis as the most likely diagnosis.

Seborrheic keratosis (SK) is the most common benign skin tumor in older adults with the incidence increasing with age. It is typically oval or round
and brown lesions mostly in sun-exposed areas with adherent greasy scales. The color may range from black to tan. Usually, SK has a
velvety verrucous (warty) surface and appears stuck on. However, some lesions are so verrucous that may resemble warts.

(Option A) Actinic keratosis is characterized by flat small scaly lesions on the sun-exposed area of old adults, especially the back of the hands.
Lesions can be multiple. Actinic keratosis is precancerous with the potential to become squamous cell carcinoma.

i Ea
Actinic keratosis - Note the flat appearance and scales of the lesion','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-c83dc868da21","duplicate_sources":[{"record_id":"7d52b1f867d4c451d2c1","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":15,"source_qid":null},{"record_id":"1e2cdec1927377ba1b4a","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":44,"source_qid":null},{"record_id":"24828d8514b7165d3933","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":233,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"7d52b1f867d4c451d2c1","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":15,"source_qid":null,"domain_hint":"Dermatology","stem":"John, 60 years of age, presents to your office because he is concerned about a skin lesion on his forearm. The dermatoscopic view of the lesion is\nshown in the following photograph. Which one of the following could be the most likely diagnosis?","options":{},"source_answer":"E","source_explanation":"The photograph shows an oval brown plaque on a sun-exposed area in an old man. There is also keratotic plugging in the surface of the lesion\n(yellowish-colored). These features are characteristic of seborrheic keratosis as the most likely diagnosis.\n\nSeborrheic keratosis (SK) is the most common benign skin tumor in older adults with the incidence increasing with age. It is typically oval or round\nand brown lesions mostly in sun-exposed areas with adherent greasy scales. The color may range from black to tan. Usually, SK has a\nvelvety verrucous (warty) surface and appears stuck on. However, some lesions are so verrucous that may resemble warts.\n\n(Option A) Actinic keratosis is characterized by flat small scaly lesions on the sun-exposed area of old adults, especially the back of the hands.\nLesions can be multiple. Actinic keratosis is precancerous with the potential to become squamous cell carcinoma.\n\ni Ea\nActinic keratosis - Note the flat appearance and scales of the lesion","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"c83dc868da21c62a55b9e46ff30093d66abc71ea","duplicate_group_id":"exact-c83dc868da21","duplicate_sources":[{"record_id":"7d52b1f867d4c451d2c1","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":15,"source_qid":null},{"record_id":"1e2cdec1927377ba1b4a","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":44,"source_qid":null},{"record_id":"24828d8514b7165d3933","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":233,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_