INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d0159dda89b5bcedb42a','Dermatology amedex 2025.pdf','18','Dermatology','A 65-year-old man presents with an exquisitely painful vesicular rash, which has been present for the past 7 days and
is increasingly painful. The rash is shown in the following photograph. His past medical history is unremarkable.
Physical examination is otherwise inconclusive. Which one of the following is the most appropriate immediate
management?',NULL,'C','The appearance of the rash and the history suggest herpes zoster (shingles) infection as the most likely diagnosis.

Herpes zoster (shingles) is caused by the reactivation of the varicella-zoster virus (VZV). It usually occurs in adults but
can be seen in children and in the first 2 years of life if there has been a history of maternal varicella.

Pain is a significant complaint in patients with shingles. Tricyclic antidepressants and the anticonvulsant gabapentin
are the most effective medications for pain control in neuropathic pain associated with shingles.

(Options A and B) Antiviral agents such as famciclovir, valacyclovir, or acyclovir should be used in any patient seen
within 72 hours of the onset of vesicles, all patients with ophthalmic herpes zoster, and in immunocompromised
patients. For pregnant women, only acyclovir (first line) or valaciclovir (second line) are used because the safety of
famciclovir during pregnancy has yet to be established.

(Option D) Varicella zoster immunoglobulin (VZIG) and vaccine are used for prophylaxis. Their use is not effective in
the treatment or for pain control after the infection has established.

(Option E) Promethazine is not effective for pain control in shingles.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[18],"source_qid":null,"duplicate_group_id":"exact-e02e39b834c2","duplicate_sources":[{"record_id":"d0159dda89b5bcedb42a","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":18,"source_qid":null},{"record_id":"dbe1a41788df3086e8d6","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":1,"source_qid":null},{"record_id":"20410ffa08f236b4cbbb","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":231,"source_qid":"820"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"d0159dda89b5bcedb42a","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":18,"supporting_pages":[18],"source_qid":null,"domain_hint":"Dermatology","stem":"A 65-year-old man presents with an exquisitely painful vesicular rash, which has been present for the past 7 days and\nis increasingly painful. The rash is shown in the following photograph. His past medical history is unremarkable.\nPhysical examination is otherwise inconclusive. Which one of the following is the most appropriate immediate\nmanagement?","options":{},"source_answer":"C","source_explanation":"The appearance of the rash and the history suggest herpes zoster (shingles) infection as the most likely diagnosis.\n\nHerpes zoster (shingles) is caused by the reactivation of the varicella-zoster virus (VZV). It usually occurs in adults but\ncan be seen in children and in the first 2 years of life if there has been a history of maternal varicella.\n\nPain is a significant complaint in patients with shingles. Tricyclic antidepressants and the anticonvulsant gabapentin\nare the most effective medications for pain control in neuropathic pain associated with shingles.\n\n(Options A and B) Antiviral agents such as famciclovir, valacyclovir, or acyclovir should be used in any patient seen\nwithin 72 hours of the onset of vesicles, all patients with ophthalmic herpes zoster, and in immunocompromised\npatients. For pregnant women, only acyclovir (first line) or valaciclovir (second line) are used because the safety of\nfamciclovir during pregnancy has yet to be established.\n\n(Option D) Varicella zoster immunoglobulin (VZIG) and vaccine are used for prophylaxis. Their use is not effective in\nthe treatment or for pain control after the infection has established.\n\n(Option E) Promethazine is not effective for pain control in shingles.","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","pregnan","prophyl","treatment","vaccin"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"e02e39b834c229098745f235314f26a2f1d27b31","duplicate_group_id":"exact-e02e39b834c2","duplicate_sources":[{"record_id":"d0159dda89b5bcedb42a","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":18,"source_qid":null},{"record_id":"dbe1a41788df3086e8d6","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":1,"source_qid":null},{"record_id":"20410ffa08f236b4cbbb","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":231,"source_qid":"820"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
