INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3fd81d9d3bd0cd19b9a6','Dermatology amedex 2025.pdf','19','Dermatology','Which one of the following statements is correct about lipomas?','{"A":"A. Lipoma is a premalignant lesion.","B":"OB. Lipomas are usually lobulated.","C":"C. Lipomas cannot be tethered to the skin.","D":"D. Lipomas often occur in the scrotum.","E":"E. Lipomas are invariably subcutaneous."}','B','Lipomas are common benign tumors of mature fat cells that can be seen in any site of the
body containing fatty tissue. They are not premalignant (option A).

Although they frequently occur in the subcutaneous fat tissue, it is not uncommon to see
lipomas in the deeper layers such as beneath the fascia or within muscles. Therefore, they are
not invariably subcutaneous (option E) and can be found in deeper layers as well

As there is very little fat in the scrotum, lipomas almost never occur there (option D), but fat
deposition within the spermatic cord may be seen. Unlike lipomas, epidermoid cysts of the
scrotum are common.

Lipomas are usually freely mobile and not attached to the overlying skin; however, in areas
such as the back of the neck or the trunk, where the skin has less mobility, they could be less
mobile or even immobile. This fact makes option C incorrect.

A lipoma''s most characteristic physical feature is the lobulated contour, which can reliably
differentiate it from an epidermoid cyst and its smooth contour.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[19],"source_qid":null,"duplicate_group_id":"exact-112873ab39ae","duplicate_sources":[{"record_id":"3fd81d9d3bd0cd19b9a6","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":19,"source_qid":null},{"record_id":"fe6a2ebb5ad1244c6bd1","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":307,"source_qid":null},{"record_id":"95b0ac08477a8068a436","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":308,"source_qid":null},{"record_id":"f421d54ab03df3e34979","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":212,"source_qid":"628"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"3fd81d9d3bd0cd19b9a6","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":19,"supporting_pages":[19],"source_qid":null,"domain_hint":"Dermatology","stem":"Which one of the following statements is correct about lipomas?","options":{"A":"A. Lipoma is a premalignant lesion.","B":"OB. Lipomas are usually lobulated.","C":"C. Lipomas cannot be tethered to the skin.","D":"D. Lipomas often occur in the scrotum.","E":"E. Lipomas are invariably subcutaneous."},"source_answer":"B","source_explanation":"Lipomas are common benign tumors of mature fat cells that can be seen in any site of the\nbody containing fatty tissue. They are not premalignant (option A).\n\nAlthough they frequently occur in the subcutaneous fat tissue, it is not uncommon to see\nlipomas in the deeper layers such as beneath the fascia or within muscles. Therefore, they are\nnot invariably subcutaneous (option E) and can be found in deeper layers as well\n\nAs there is very little fat in the scrotum, lipomas almost never occur there (option D), but fat\ndeposition within the spermatic cord may be seen. Unlike lipomas, epidermoid cysts of the\nscrotum are common.\n\nLipomas are usually freely mobile and not attached to the overlying skin; however, in areas\nsuch as the back of the neck or the trunk, where the skin has less mobility, they could be less\nmobile or even immobile. This fact makes option C incorrect.\n\nA lipoma''s most characteristic physical feature is the lobulated contour, which can reliably\ndifferentiate it from an epidermoid cyst and its smooth contour.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"112873ab39ae7eef2564180c1eb7241e3bf985d6","duplicate_group_id":"exact-112873ab39ae","duplicate_sources":[{"record_id":"3fd81d9d3bd0cd19b9a6","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":19,"source_qid":null},{"record_id":"fe6a2ebb5ad1244c6bd1","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":307,"source_qid":null},{"record_id":"95b0ac08477a8068a436","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":308,"source_qid":null},{"record_id":"f421d54ab03df3e34979","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":212,"source_qid":"628"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
