INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('2c40a3ba12ccaa32de41','Dermatology amedex 2025.pdf','20','Dermatology','Jane, 21 years old, presents with a painless lesion on the distal interphalangeal joint of her right middle
finger. The lesion has been present for the past 2 months and increased in size. The lesion is shown in the
following photograph. On examination, she is otherwise healthy. Which one of the following is the most likely
diagnosis?',NULL,'C','The fleshy red lesion on the distal interphalangeal joint of this patient is consistent with the diagnosis of

pyogenic granuloma (PG). PG is a common benign acquired vascular neoplasm of the skin and mucous
membrane. The etiology is unknown. Some think it might be due to minor trauma, especially for PGs of

fingers. Pyogenic granuloma is a misnomer because the lesion is neither pyogenic nor granuloma.

It is an erythematosus (fleshy red) dome-shaped papule or nodule that bleeds easily and is prone to
ulceration, erosion, and crusting. It is most often seen in adolescents and young adults. Up to 5% of
pregnant women may experience it.

Although very rare, PGs have been reported in the gastrointestinal tract, the larynx, nasal mucosa,
conjunctiva, and cornea.

(Options A, D, and E) Abscess, epidermoid cyst, and mucous cyst are covered with skin.

(Option B) Pyoderma gangrenosum typically presents with a well-defined border, which is usually violet or
blue.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[20],"source_qid":null,"duplicate_group_id":"exact-6b5661cbb419","duplicate_sources":[{"record_id":"2c40a3ba12ccaa32de41","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":20,"source_qid":null},{"record_id":"91ebce6552a084767dc9","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":19,"source_qid":null},{"record_id":"79868981a7914f15cb71","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":224,"source_qid":"37"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":"manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00021.jpg","asset_preview_url":"https://drive.google.com/file/d/1RvumS6-Xvss4wLovVOKRqzDLAiJitMSm/preview"}','manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00021.jpg','https://drive.google.com/thumbnail?id=1RvumS6-Xvss4wLovVOKRqzDLAiJitMSm&sz=w1600',NULL,NULL,'needs_verification','[]','medium','{"record_id":"2c40a3ba12ccaa32de41","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":20,"supporting_pages":[20],"source_qid":null,"domain_hint":"Dermatology","stem":"Jane, 21 years old, presents with a painless lesion on the distal interphalangeal joint of her right middle\nfinger. The lesion has been present for the past 2 months and increased in size. The lesion is shown in the\nfollowing photograph. On examination, she is otherwise healthy. Which one of the following is the most likely\ndiagnosis?","options":{},"source_answer":"C","source_explanation":"The fleshy red lesion on the distal interphalangeal joint of this patient is consistent with the diagnosis of\n\npyogenic granuloma (PG). PG is a common benign acquired vascular neoplasm of the skin and mucous\nmembrane. The etiology is unknown. Some think it might be due to minor trauma, especially for PGs of\n\nfingers. Pyogenic granuloma is a misnomer because the lesion is neither pyogenic nor granuloma.\n\nIt is an erythematosus (fleshy red) dome-shaped papule or nodule that bleeds easily and is prone to\nulceration, erosion, and crusting. It is most often seen in adolescents and young adults. Up to 5% of\npregnant women may experience it.\n\nAlthough very rare, PGs have been reported in the gastrointestinal tract, the larynx, nasal mucosa,\nconjunctiva, and cornea.\n\n(Options A, D, and E) Abscess, epidermoid cyst, and mucous cyst are covered with skin.\n\n(Option B) Pyoderma gangrenosum typically presents with a well-defined border, which is usually violet or\nblue.","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["pregnan"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"6b5661cbb419503643f3b40dd99d91388137b923","duplicate_group_id":"exact-6b5661cbb419","duplicate_sources":[{"record_id":"2c40a3ba12ccaa32de41","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":20,"source_qid":null},{"record_id":"91ebce6552a084767dc9","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":19,"source_qid":null},{"record_id":"79868981a7914f15cb71","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":224,"source_qid":"37"}],"visual_assets":["manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00021.jpg"],"visual_asset":"manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00021.jpg"}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
