INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('fd964706e4112648ae67','Dermatology amedex 2025.pdf','25','Dermatology','A 61-year-old male farmer presents to your clinic because he is concerned about a skin lesion on his face. The lesion
is shown in the accompanying photograph. Which one of the following is the most likely diagnosis?','{"A":"A. Keratoacanthoma.","B":"OB. Basal cell carcinoma.","C":"C. Implantation dermoid cyst.","D":"D. Amelanotic malignant melanoma.","E":"E. Squamous cell carcinoma."}','B','The appearance of the lesion is consistent with nodular basal cell carcinoma (BCC). BCC is the most common skin
cancer. Unlike squamous cell carcinoma (SCC), BCC can be seen in non-photoexposed areas as well. Nodular BCC is
the most common subtype. The pearly appearance, shiny surface and telangiectasis are characteristic features.
Additionally, the lesion in the photograph has undergone ulceration at parts.

(Option A) Keratoacanthoma has the central crater filled with necrotic tissue, which is not seen here.

(Option C) Implantation dermoid cysts are firm subdermal cystic nodules that often occur following a penetrating
trauma. The fingertips of mechanics are the most common site for such lesions.

(Option D) Amelanotic melanoma can resemble a nodular BCC; although it will lack the pearly appearance of BCC,
which can be noted in this photograph.

(Option E) Squamous cell carcinoma does not fit the clinical picture. It usually presents with an ulcerating plaque.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[25],"source_qid":null,"duplicate_group_id":"exact-1aa7355c64d1","duplicate_sources":[{"record_id":"fd964706e4112648ae67","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":25,"source_qid":null},{"record_id":"a8973423bebbb8f69656","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":195,"source_qid":null},{"record_id":"e520d3ddd4c1a1e360c7","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":246,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"fd964706e4112648ae67","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":25,"supporting_pages":[25],"source_qid":null,"domain_hint":"Dermatology","stem":"A 61-year-old male farmer presents to your clinic because he is concerned about a skin lesion on his face. The lesion\nis shown in the accompanying photograph. Which one of the following is the most likely diagnosis?","options":{"A":"A. Keratoacanthoma.","B":"OB. Basal cell carcinoma.","C":"C. Implantation dermoid cyst.","D":"D. Amelanotic malignant melanoma.","E":"E. Squamous cell carcinoma."},"source_answer":"B","source_explanation":"The appearance of the lesion is consistent with nodular basal cell carcinoma (BCC). BCC is the most common skin\ncancer. Unlike squamous cell carcinoma (SCC), BCC can be seen in non-photoexposed areas as well. Nodular BCC is\nthe most common subtype. The pearly appearance, shiny surface and telangiectasis are characteristic features.\nAdditionally, the lesion in the photograph has undergone ulceration at parts.\n\n(Option A) Keratoacanthoma has the central crater filled with necrotic tissue, which is not seen here.\n\n(Option C) Implantation dermoid cysts are firm subdermal cystic nodules that often occur following a penetrating\ntrauma. The fingertips of mechanics are the most common site for such lesions.\n\n(Option D) Amelanotic melanoma can resemble a nodular BCC; although it will lack the pearly appearance of BCC,\nwhich can be noted in this photograph.\n\n(Option E) Squamous cell carcinoma does not fit the clinical picture. It usually presents with an ulcerating plaque.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"1aa7355c64d15200a9311d0506512f32622c4750","duplicate_group_id":"exact-1aa7355c64d1","duplicate_sources":[{"record_id":"fd964706e4112648ae67","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":25,"source_qid":null},{"record_id":"a8973423bebbb8f69656","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":195,"source_qid":null},{"record_id":"e520d3ddd4c1a1e360c7","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path