INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7254fcb612a28f874111','Dermatology amedex 2025.pdf','26','Dermatology','Which one of the following is the most likely diagnosis of the lesion shown in the accompanying
photograph?','{"A":"A. Keratoacanthoma.","B":"B. Basal cell carcinoma.","C":"C. Seborrheic dermatitis.","D":"OD. Malignant melanoma.","E":"E. Simple nevus."}','D','The photograph shows a pigmented lesion on the left side of the nose. With pigmentation, the two most
likely diagnoses are simple nevi or malignant melanoma. Early melanomas may be differentiated from
benign nevi by the ABCD:

e A- Asymmetry

¢ B - Border irregularity

¢ C- Color that tends to be very dark black or blue and variable
¢ D- Diameter 26mm

The lesion is asymmetrical (A) and has irregular borders (B). It shows variegation (variation in colors) (C)
and seems to be larger than 6mm; therefore, melanoma seems to be the most likely diagnosis.

Keratoacanthoma, basal cell carcinoma, and seborrhoeic dermatitis present quite differently.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[26],"source_qid":null,"duplicate_group_id":"exact-98730d0b6a6f","duplicate_sources":[{"record_id":"7254fcb612a28f874111","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":26,"source_qid":null},{"record_id":"887041483c7bcd0e7c41","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":202,"source_qid":"615"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"7254fcb612a28f874111","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":26,"supporting_pages":[26],"source_qid":null,"domain_hint":"Dermatology","stem":"Which one of the following is the most likely diagnosis of the lesion shown in the accompanying\nphotograph?","options":{"A":"A. Keratoacanthoma.","B":"B. Basal cell carcinoma.","C":"C. Seborrheic dermatitis.","D":"OD. Malignant melanoma.","E":"E. Simple nevus."},"source_answer":"D","source_explanation":"The photograph shows a pigmented lesion on the left side of the nose. With pigmentation, the two most\nlikely diagnoses are simple nevi or malignant melanoma. Early melanomas may be differentiated from\nbenign nevi by the ABCD:\n\ne A- Asymmetry\n\n¢ B - Border irregularity\n\n¢ C- Color that tends to be very dark black or blue and variable\n¢ D- Diameter 26mm\n\nThe lesion is asymmetrical (A) and has irregular borders (B). It shows variegation (variation in colors) (C)\nand seems to be larger than 6mm; therefore, melanoma seems to be the most likely diagnosis.\n\nKeratoacanthoma, basal cell carcinoma, and seborrhoeic dermatitis present quite differently.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"98730d0b6a6faa70f5ec6bbe667272645c634bac","duplicate_group_id":"exact-98730d0b6a6f","duplicate_sources":[{"record_id":"7254fcb612a28f874111","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":26,"source_qid":null},{"record_id":"887041483c7bcd0e7c41","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":202,"source_qid":"615"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
