INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('bc449f7d2cc0172533ac','Dermatology amedex 2025.pdf','29','Dermatology','Which one of the following parts of the nail is more commonly affected by tinea unguium?','{"A":"A. Nail fold.","B":"B. Nail bed.","C":"OC. Nail plate.","D":"D. Cuticle.","E":"E. Entire nail including nail bed."}','C','Tinea unguium is the infection of the fingernails or toenails caused by dermatophytes. Generally, fungal infection of
the nails is termed onychomycosis (plural: onychomycoses). Onychomycoses which are specifically caused by
dermatophytes are referred to as tinea unguium. There are three distinctive presentations:

Distal subungual

This presentation is the most common form of fungal nail infection. The most common culprit to this presentation is
Trichophyton rubrum. It begins with a whitish, yellowish or brownish discoloration of the distal corner of the nail,
which gradually spreads to the entire width of the nail plate and then slowly extends toward the cuticle.

Proximal subungual

The most common cause is Trichophyton rubrum. It presents with whitish, yellowish, and brownish discoloration of
the nail, starting from around the cuticle and spreading distally.

White superficial

The most common cause is Trichophyton mentagrophytes. It starts with a dull white spot on the surface of the nail
plate. The whole nail plate may eventually be involved. The white areas are soft and can be scraped gently to obtain
a sample.

In all three types, the nail plate is the often affected part.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[29],"source_qid":null,"duplicate_group_id":"exact-4b008004e07b","duplicate_sources":[{"record_id":"bc449f7d2cc0172533ac","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":29,"source_qid":null},{"record_id":"f3ffe0f63bdb4068c427","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":206,"source_qid":null},{"record_id":"24a2896740ab839e6de5","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":207,"source_qid":null},{"record_id":"fbcb778ba695317a4faf","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":218,"source_qid":"635"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"bc449f7d2cc0172533ac","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":29,"supporting_pages":[29],"source_qid":null,"domain_hint":"Dermatology","stem":"Which one of the following parts of the nail is more commonly affected by tinea unguium?","options":{"A":"A. Nail fold.","B":"B. Nail bed.","C":"OC. Nail plate.","D":"D. Cuticle.","E":"E. Entire nail including nail bed."},"source_answer":"C","source_explanation":"Tinea unguium is the infection of the fingernails or toenails caused by dermatophytes. Generally, fungal infection of\nthe nails is termed onychomycosis (plural: onychomycoses). Onychomycoses which are specifically caused by\ndermatophytes are referred to as tinea unguium. There are three distinctive presentations:\n\nDistal subungual\n\nThis presentation is the most common form of fungal nail infection. The most common culprit to this presentation is\nTrichophyton rubrum. It begins with a whitish, yellowish or brownish discoloration of the distal corner of the nail,\nwhich gradually spreads to the entire width of the nail plate and then slowly extends toward the cuticle.\n\nProximal subungual\n\nThe most common cause is Trichophyton rubrum. It presents with whitish, yellowish, and brownish discoloration of\nthe nail, starting from around the cuticle and spreading distally.\n\nWhite superficial\n\nThe most common cause is Trichophyton mentagrophytes. It starts with a dull white spot on the surface of the nail\nplate. The whole nail plate may eventually be involved. The white areas are soft and can be scraped gently to obtain\na sample.\n\nIn all three types, the nail plate is the often affected part.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"4b008004e07b8ddae0c58c2b35076260f752dd4e","duplicate_group_id":"exact-4b008004e07b","duplicate_sources":[{"record_id":"bc449f7d2cc0172533ac","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":29,"source_qid":null},{"record_id":"f3ffe0f63bdb4068c427","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":206,"source_qid":null},{"record_id":"24a2896740ab839e6de5","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":207,"source_qid":null},{"record_id":"fbcb778ba695317a4faf","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":218,"source_qid":"635"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
