INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('cf0e71f3a70cc642c139','Dermatology amedex 2025.pdf','31','Dermatology','An 8-year-old boy is brought to your practice with a complaint of itchy lesions shown in the following. He has been recently
prescribed cotrimoxazole. Which on of the following could be the most likely diagnosis?',NULL,'A','The photograph shows multiple round lesions of different sizes over the face, chest, abdomen, and arm. The lesions have
prominent circular edges with centers being clear. With itchiness in the history, dermatophytic infection (tinea) is the most likely
diagnosis.

Tinea is caused by dermatophytes fungi that affect any part of the skin. The typical rash of tinea has the following characteristic
features:

e Annular or arcuate (arc-shaped)
¢ Scaly and itchy
¢ Definite edges and central clearing as it expands

(Option A) Psoriasis is characterized by erythematous patches distributed symmetrically. A unique feature of psoriasis is the
silvery scaling of the patches absent here. Moreover, psoriatic lesions do not have central clearing.

(Option C) Contact dermatitis can cause an itchy scaly erythematous rash without central clearing.

(Option D) Allergic reactions to the medication (e.g. cotrimoxazole) can cause various clinical pictures, including an itchy
erythematous rash but without central clearing. Wheels (hives) have clear centers, but the lesion''s appearance differs from those
shown in the photograph. There is usually no scaling.

(Option E) Tinea versicolor presents with hypo/hyperpigmented macules of different sizes with slight scaling and itching. There is
no central clearing of the lesions.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[31],"source_qid":null,"duplicate_group_id":"exact-3a84561f302e","duplicate_sources":[{"record_id":"cf0e71f3a70cc642c139","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":31,"source_qid":null},{"record_id":"99381848a7f7a651bf91","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":33,"source_qid":null},{"record_id":"ba154ac4ee7b840972c0","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":221,"source_qid":"637"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":"manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00035.jpg","asset_preview_url":"https://drive.google.com/file/d/1AjSlz2XpBC_Xnny3TNpRqxZLFtwyF2Ar/preview"}','manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00035.jpg','https://drive.google.com/thumbnail?id=1AjSlz2XpBC_Xnny3TNpRqxZLFtwyF2Ar&sz=w1600',NULL,NULL,'needs_verification','[]','low','{"record_id":"cf0e71f3a70cc642c139","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":31,"supporting_pages":[31],"source_qid":null,"domain_hint":"Dermatology","stem":"An 8-year-old boy is brought to your practice with a complaint of itchy lesions shown in the following. He has been recently\nprescribed cotrimoxazole. Which on of the following could be the most likely diagnosis?","options":{},"source_answer":"A","source_explanation":"The photograph shows multiple round lesions of different sizes over the face, chest, abdomen, and arm. The lesions have\nprominent circular edges with centers being clear. With itchiness in the history, dermatophytic infection (tinea) is the most likely\ndiagnosis.\n\nTinea is caused by dermatophytes fungi that affect any part of the skin. The typical rash of tinea has the following characteristic\nfeatures:\n\ne Annular or arcuate (arc-shaped)\n¢ Scaly and itchy\n¢ Definite edges and central clearing as it expands\n\n(Option A) Psoriasis is characterized by erythematous patches distributed symmetrically. A unique feature of psoriasis is the\nsilvery scaling of the patches absent here. Moreover, psoriatic lesions do not have central clearing.\n\n(Option C) Contact dermatitis can cause an itchy scaly erythematous rash without central clearing.\n\n(Option D) Allergic reactions to the medication (e.g. cotrimoxazole) can cause various clinical pictures, including an itchy\nerythematous rash but without central clearing. Wheels (hives) have clear centers, but the lesion''s appearance differs from those\nshown in the photograph. There is usually no scaling.\n\n(Option E) Tinea versicolor presents with hypo/hyperpigmented macules of different sizes with slight scaling and itching. There is\nno central clearing of the lesions.","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"3a84561f302eef2b67519f8b339bcda97d45c3a4","duplicate_group_id":"exact-3a84561f302e","duplicate_sources":[{"record_id":"cf0e71f3a70cc642c139","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbo