matology amedex 2025.pdf","source_page":34,"source_qid":null},{"record_id":"7a58a19ceb078c8b9e39","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":284,"source_qid":null},{"record_id":"69823027e5cd4c417141","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":210,"source_qid":"627"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
