INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6d7af66e1bac502f8f3b','Dermatology amedex 2025.pdf','36','Dermatology','A 45-year-old woman presents with a mole on the lower eyelid of her left eye as shown in the
following photograph. Which of the following would be the most appropriate management?','{"A":"A. Excision of the lesion under local anesthesia.","B":"B. Review in one month.","C":"C. Reassure that the lesion is benign.","D":"OD. Refer the patient to a plastic surgeon.","E":"E. Apply topical imiquimod."}','D','The photograph shows an irregular pigmented lesion on the lower eyelid of the left eye. The
appearance of the lesion is suggestive of melanoma and complete excision and histopathological
studies are indicated. Due to the anatomical location of the lesion, excision should be performed by
a plastic surgeon to avoid tissue destruction or loss of function in such an anatomically delicate
area.

When melanoma is suspected, excisional biopsy should be done as soon as possible; therefore
‘review in one month’ (option B) and ‘reassurance’ (option C) are incorrect answers. Imiquimod
(option E) is not an appropriate management option for melanoma.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[36],"source_qid":null,"duplicate_group_id":"exact-c919ccddd04d","duplicate_sources":[{"record_id":"6d7af66e1bac502f8f3b","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":36,"source_qid":null},{"record_id":"961e60f78a65a9de73bc","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":82,"source_qid":null},{"record_id":"ccf464cc4b19cca53af2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":214,"source_qid":"631"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"6d7af66e1bac502f8f3b","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":36,"supporting_pages":[36],"source_qid":null,"domain_hint":"Dermatology","stem":"A 45-year-old woman presents with a mole on the lower eyelid of her left eye as shown in the\nfollowing photograph. Which of the following would be the most appropriate management?","options":{"A":"A. Excision of the lesion under local anesthesia.","B":"B. Review in one month.","C":"C. Reassure that the lesion is benign.","D":"OD. Refer the patient to a plastic surgeon.","E":"E. Apply topical imiquimod."},"source_answer":"D","source_explanation":"The photograph shows an irregular pigmented lesion on the lower eyelid of the left eye. The\nappearance of the lesion is suggestive of melanoma and complete excision and histopathological\nstudies are indicated. Due to the anatomical location of the lesion, excision should be performed by\na plastic surgeon to avoid tissue destruction or loss of function in such an anatomically delicate\narea.\n\nWhen melanoma is suspected, excisional biopsy should be done as soon as possible; therefore\n‘review in one month’ (option B) and ‘reassurance’ (option C) are incorrect answers. Imiquimod\n(option E) is not an appropriate management option for melanoma.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"c919ccddd04de6d03a33766bf16222f15894b28e","duplicate_group_id":"exact-c919ccddd04d","duplicate_sources":[{"record_id":"6d7af66e1bac502f8f3b","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":36,"source_qid":null},{"record_id":"961e60f78a65a9de73bc","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":82,"source_qid":null},{"record_id":"ccf464cc4b19cca53af2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":214,"source_qid":"631"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_