INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6ca92e0b6aed9236855d','Dermatology amedex 2025.pdf','38','Dermatology','The 7-year-old Evie is brought to your general practice by her mother who is concerned about a rash she has developed and is shown in the following photograph. The rash appeared almost two months ago on her abdomen and has spread to the extent evident in the photo. There is no complaint of pain or itching, but a few lesions have ulcerated. Evie is otherwise healthy and has not had any serious illnesses so far. Her growth charts are all normal. Physical examination is otherwise normal. She goes to school and has two younger brothers and sisters at home. Which one of the following is the correct advice to give?','{"A":"She should be excluded from school until the resolution of the rash.","B":"She can go to school but should use a separate towel and other personal items.","C":"She should be given oral acyclovir.","D":"Cryotherapy with liquid nitrogen is the treatment of choice for the rash.","E":"She should use topical steroids."}','B',NULL,'{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[38],"source_qid":null,"duplicate_group_id":null,"duplicate_sources":[],"parser_version":"manual-review-batch021-2026-09-24","parser_mode":"manual_visual_review_batch021","text_method":"manual_visual_transcription","visual_asset":"manual_review_assets/Dermatology_amedex_2025__57e6ac47a58d/page_00038.jpg","asset_preview_url":"https://drive.google.com/file/d/1TDgF6YjXMB2OxtFUtOE_hKpEjsg1pIom/preview"}','manual_review_assets/Dermatology_amedex_2025__57e6ac47a58d/page_00038.jpg','https://drive.google.com/thumbnail?id=1TDgF6YjXMB2OxtFUtOE_hKpEjsg1pIom&sz=w1