INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('fe19963abfef557c6f5b','Dermatology amedex 2025.pdf','42','Dermatology','A 17-year-old boy presents to your practice with lesion shown in the accompanying photograph. The lesions
have failed to improve with conventional therapy. Which one of the following would be the most appropriate
management?','{"A":"A. Doxycycline.","B":"B. Hydrocortisone 1% cream.","C":"OC. Isotretinoin.","D":"D. Benzoyl peroxide.","E":"E. Occlusive makeup."}','C','The photograph shows severe cystic acne and scarring. Systemic isotretinoin (Raccutane®) is the treatment of last
resort for severe cystic acne or acne with scarring if conventional therapy fails. In this patient with no response to
conventional therapy, systemic isotretinoin is the most appropriate management option.

For mild papulopustular acne, the use of either a topical retinoid or benzoyl peroxide is recommended. If the
treatment fails, topical clindamycin or erythromycin is added. Salicylic acid, 3% to 5% in 70% ethanol, can be used
for mild truncal acne.

For moderate papulopustular acne +/- trunk involvement +/- nodules, not only the strength of topical retinoids or
benzoyl peroxide should be increased, but oral rather than topical antibiotics should be used. Oral doxycycline is the
first-line option. Tetracycline or minocycline can be used alternatively as second- and third-line options, respectively.
Erythromycin (250-500mg, twice daily) is the choice if tetracyclines are not tolerated or contraindicated (e.g. in
pregnancy).

For moderate to severe acne +/- nodules +/- cysts, topical adapalene or tretinoin plus antibiotics is used. If there is
no improvement by 6 weeks or insufficient response by 12 weeks, the antibiotic is changed or the dose is increased.
If such measures fail, referral for systemic treatment with isotretinoin is the most appropriate management.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[42],"source_qid":null,"duplicate_group_id":"exact-5e8280cbfe93","duplicate_sources":[{"record_id":"fe19963abfef557c6f5b","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":42,"source_qid":null},{"record_id":"f3b338976f236e3bd862","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":210,"source_qid":null},{"record_id":"1f5c6da0b73c101fdcc9","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":217,"source_qid":"634"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"fe19963abfef557c6f5b","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":42,"supporting_pages":[42],"source_qid":null,"domain_hint":"Dermatology","stem":"A 17-year-old boy presents to your practice with lesion shown in the accompanying photograph. The lesions\nhave failed to improve with conventional therapy. Which one of the following would be the most appropriate\nmanagement?","options":{"A":"A. Doxycycline.","B":"B. Hydrocortisone 1% cream.","C":"OC. Isotretinoin.","D":"D. Benzoyl peroxide.","E":"E. Occlusive makeup."},"source_answer":"C","source_explanation":"The photograph shows severe cystic acne and scarring. Systemic isotretinoin (Raccutane®) is the treatment of last\nresort for severe cystic acne or acne with scarring if conventional therapy fails. In this patient with no response to\nconventional therapy, systemic isotretinoin is the most appropriate management option.\n\nFor mild papulopustular acne, the use of either a topical retinoid or benzoyl peroxide is recommended. If the\ntreatment fails, topical clindamycin or erythromycin is added. Salicylic acid, 3% to 5% in 70% ethanol, can be used\nfor mild truncal acne.\n\nFor moderate papulopustular acne +/- trunk involvement +/- nodules, not only the strength of topical retinoids or\nbenzoyl peroxide should be increased, but oral rather than topical antibiotics should be used. Oral doxycycline is the\nfirst-line option. Tetracycline or minocycline can be used alternatively as second- and third-line options, respectively.\nErythromycin (250-500mg, twice daily) is the choice if tetracyclines are not tolerated or contraindicated (e.g. in\npregnancy).\n\nFor moderate to severe acne +/- nodules +/- cysts, topical adapalene or tretinoin plus antibiotics is used. If there is\nno improvement by 6 weeks or insufficient response by 12 weeks, the antibiotic is changed or the dose is increased.\nIf such measures fail, referral for systemic treatment with isotretinoin is the most appropriate management.","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","antibiotic","dose","management","pregnan","therapy","treatment"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"5e8280cbfe930f50d99f9e13a82b1c7e3409095e","duplicate_group_id":"exact-5e8280cbfe93","duplicate_sources":[{"record_id":"fe19963abfef557c6f5b","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":42,"source_qid":null},{"record_id":"f3b338976f236e3bd862","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":210,"source_qid":null},{"record_id":"1f5c6da0b73c101fdcc9","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":217,"source_qid":"634"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
