INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1f19bc5bcbf2b08d5dbc','Dermatology amedex 2025.pdf','44','Dermatology','Jesse, 57 years old, presents to your GP clinic with concerns about a spreading
brown spot on his left cheek. Physical examination suggests melanoma. Which
one of the following is the most appropriate step in management?','{"A":"A. Excisional biopsy.","B":"B. Punch biopsy.","C":"OC. Referral to a plastic surgeon.","D":"D. Radiotherapy.","E":"E. Chemotherapy."}','C','Based on current guidelines, any suspicious lesion for melanoma should
undergo an initial excisional biopsy (option A) for confirmation. Other types of
biopsies such as punch biopsy (option B) are neither as accurate nor
recommended.

However, lesions in sensitive anatomical areas such as the face and neck should
be biopsied by a plastic surgeon; therefore, referral to a plastic surgeon is the
best action to take at this stage.

The initial management of melanoma is excision. Other modalities such as
chemotherapy (option E) or radiotherapy (option D) might be considered later
for advanced or metastatic melanomas, but not at this stage.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[44],"source_qid":null,"duplicate_group_id":"exact-05cd4af3bbb4","duplicate_sources":[{"record_id":"1f19bc5bcbf2b08d5dbc","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":44,"source_qid":null},{"record_id":"9ab5bc1222845d52925b","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":123,"source_qid":null},{"record_id":"414a0e4ff92407f2c86c","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":122,"source_qid":null},{"record_id":"0cc1d497494475600a25","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":240,"source_qid":"1780"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"1f19bc5bcbf2b08d5dbc","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":44,"supporting_pages":[44],"source_qid":null,"domain_hint":"Dermatology","stem":"Jesse, 57 years old, presents to your GP clinic with concerns about a spreading\nbrown spot on his left cheek. Physical examination suggests melanoma. Which\none of the following is the most appropriate step in management?","options":{"A":"A. Excisional biopsy.","B":"B. Punch biopsy.","C":"OC. Referral to a plastic surgeon.","D":"D. Radiotherapy.","E":"E. Chemotherapy."},"source_answer":"C","source_explanation":"Based on current guidelines, any suspicious lesion for melanoma should\nundergo an initial excisional biopsy (option A) for confirmation. Other types of\nbiopsies such as punch biopsy (option B) are neither as accurate nor\nrecommended.\n\nHowever, lesions in sensitive anatomical areas such as the face and neck should\nbe biopsied by a plastic surgeon; therefore, referral to a plastic surgeon is the\nbest action to take at this stage.\n\nThe initial management of melanoma is excision. Other modalities such as\nchemotherapy (option E) or radiotherapy (option D) might be considered later\nfor advanced or metastatic melanomas, but not at this stage.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","guideline","management","therapy"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"05cd4af3bbb42efbf6cebcc7e14b930fbb2a0f9f","duplicate_group_id":"exact-05cd4af3bbb4","duplicate_sources":[{"record_id":"1f19bc5bcbf2b08d5dbc","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":44,"source_qid":null},{"record_id":"9ab5bc1222845d52925b","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":123,"source_qid":null},{"record_id":"414a0e4ff92407f2c86c","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":122,"source_qid":null},{"record_id":"0cc1d497494475600a25","re