INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('268a76a82d2412d0fcb0','Dermatology amedex 2025.pdf','45','Dermatology','On a health check, a 75-year-old man is found to have a lesion on his left cheek. He mentions that he has
had it for three years. The lesion is illustrated in the accompanying photograph. Which one of the following
is the most likely diagnosis?','{"E":"Pigmented basal cell carcinoma."}','D','The irregular borders and different color shades of the lesion are suggestive of melanoma. Since the lesion
has been stable for 3 years, lentigo maligna melanoma (Hutchinson melanotic freckles) is the most likely
diagnosis.

Lentigo maligna melanoma is classically a pigmented macular skin lesion found on the sun-exposed facial
skin of the elderly. The color varies from black to light tan and is often variegated.

(Option A) Benign nevus tends to have smoother borders and more even coloration.

(Option B) Seborrheic keratoses are well-defined lesions with surfaces ranging from velvety to verrucous.
The color can vary from black to light tan. Color variegation is not usually a feature.

(Option C) Bowen''s disease (Squamous Cell carcinoma in situ) is a scaly plague most commonly in sun-
exposed areas. The plaque of Bowen’s disease can be mistaken for psoriasis or dermatitis.

(Option E) Basal cell carcinoma has different characteristic features such as being pearly, raised, and
associated with telangiectasis in nodular BCC, pearly thready borders in superficial BCC, and scar-like
appearance in morphoeic BCC, none of which are present here.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[45],"source_qid":null,"duplicate_group_id":"exact-3c0444c4e3bb","duplicate_sources":[{"record_id":"268a76a82d2412d0fcb0","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":45,"source_qid":null},{"record_id":"ed581f9dcc706bacdc29","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":125,"source_qid":null},{"record_id":"a86bd96725298730b50d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":213,"source_qid":"630"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":"manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00126.jpg","asset_preview_url":"https://drive.google.com/file/d/1zEENsuCZ4TiuZvWr7LJCPWHFdyW6yAiX/preview"}','manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00126.jpg','https://drive.google.com/thumbnail?id=1zEENsuCZ4TiuZvWr7LJCPWHFdyW6yAiX&sz=w1600',NULL,NULL,'needs_verification','[]','low','{"record_id":"268a76a82d2412d0fcb0","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":45,"supporting_pages":[45],"source_qid":null,"domain_hint":"Dermatology","stem":"On a health check, a 75-year-old man is found to have a lesion on his left cheek. He mentions that he has\nhad it for three years. The lesion is illustrated in the accompanying photograph. Which one of the following\nis the most likely diagnosis?","options":{"E":"Pigmented basal cell carcinoma."},"source_answer":"D","source_explanation":"The irregular borders and different color shades of the lesion are suggestive of melanoma. Since the lesion\nhas been stable for 3 years, lentigo maligna melanoma (Hutchinson melanotic freckles) is the most likely\ndiagnosis.\n\nLentigo maligna melanoma is classically a pigmented macular skin lesion found on the sun-exposed facial\nskin of the elderly. The color varies from black to light tan and is often variegated.\n\n(Option A) Benign nevus tends to have smoother borders and more even coloration.\n\n(Option B) Seborrheic keratoses are well-defined lesions with surfaces ranging from velvety to verrucous.\nThe color can vary from black to light tan. Color variegation is not usually a feature.\n\n(Option C) Bowen''s disease (Squamous Cell carcinoma in situ) is a scaly plague most commonly in sun-\nexposed areas. The plaque of Bowen’s disease can be mistaken for psoriasis or dermatitis.\n\n(Option E) Basal cell carcinoma has different characteristic features such as being pearly, raised, and\nassociated with telangiectasis in nodular BCC, pearly thready borders in superficial BCC, and scar-like\nappearance in morphoeic BCC, none of which are present here.","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"3c0444c4e3bb448329012d6470d3468ed8df1730","duplicate_group_id":"exact-3c0444c4e3bb","duplicate_sources":[{"record_id":"268a76a82d2412d0fcb0","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":45,"source_qid":null},{"record_id":"ed581f9dcc706bacdc29","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":125,"source_qid":null},{"record_id":"a86bd96725298730b50d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":213,"source_qid":"630"}],"visual_assets":["manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00126.jpg"],"visual_asset":"manual_review_assets/AMEDEX_2025_DERMATOLOGY_1-60__b2c20b5292a2/page_00126.jpg"}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
