INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3ea012ef15a8e425b2c9','Dermatology amedex 2025.pdf','49','Dermatology','John, 42 years old, presents to your GP clinic to discuss skin cancer prevention. His past medical history is
significant for a cutaneous squamous cell carcinoma (SCC) excised which was successfully treated years
ago. He has fair skin with a tendency to tan rather than burn. He denies a history of sunburns as a child.
Which one of the following is the most significant risk factor for developing another SCC?',NULL,'B','SCC is the second most common skin cancer in Australia after basal cell carcinoma. Risk factors for SCC
are:

e Unprotected exposure to ultraviolet (UV) radiation from the sun or tanning bed

e Age over 50

e Male gender

¢ Fair skin (Fitz Patrick | and II)

e¢ Immunosuppression

¢ Personal history of skin cancers (non-melanoma or melanoma)

¢ History of human papillomavirus (HPV) infection

e Precancerous skin lesions such as Bowen’s disease and actinic keratosis (AK)

¢ Chronic infections and skin inflammation from burns, scars, and other conditions

Of these risk factors, the presence of another SCC in history has the most significance (high risk). Fair skin
(option E) is another high-risk factor for SCC but not as significant as the history of another SCC. In the
absence of past history of skin cancer, it would be the correct answer.

He is under 50 and his age (option C) is not a risk factor for now. He tends to tan rather than burn (option
A) which is a protective factor. While childhood sunburns are a risk factor, their absence (option D) is not
one.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","supporting_pages":[49],"source_qid":null,"duplicate_group_id":"exact-10bc2ae826ca","duplicate_sources":[{"record_id":"3ea012ef15a8e425b2c9","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":49,"source_qid":null},{"record_id":"79e84943f9303b63645a","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":24,"source_qid":null},{"record_id":"51d10d87dfc5b455816f","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":23,"source_qid":null},{"record_id":"79ba6426f30895972253","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":242,"source_qid":"1784"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"3ea012ef15a8e425b2c9","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_year":2025,"source_page":49,"supporting_pages":[49],"source_qid":null,"domain_hint":"Dermatology","stem":"John, 42 years old, presents to your GP clinic to discuss skin cancer prevention. His past medical history is\nsignificant for a cutaneous squamous cell carcinoma (SCC) excised which was successfully treated years\nago. He has fair skin with a tendency to tan rather than burn. He denies a history of sunburns as a child.\nWhich one of the following is the most significant risk factor for developing another SCC?","options":{},"source_answer":"B","source_explanation":"SCC is the second most common skin cancer in Australia after basal cell carcinoma. Risk factors for SCC\nare:\n\ne Unprotected exposure to ultraviolet (UV) radiation from the sun or tanning bed\n\ne Age over 50\n\ne Male gender\n\n¢ Fair skin (Fitz Patrick | and II)\n\ne¢ Immunosuppression\n\n¢ Personal history of skin cancers (non-melanoma or melanoma)\n\n¢ History of human papillomavirus (HPV) infection\n\ne Precancerous skin lesions such as Bowen’s disease and actinic keratosis (AK)\n\n¢ Chronic infections and skin inflammation from burns, scars, and other conditions\n\nOf these risk factors, the presence of another SCC in history has the most significance (high risk). Fair skin\n(option E) is another high-risk factor for SCC but not as significant as the history of another SCC. In the\nabsence of past history of skin cancer, it would be the correct answer.\n\nHe is under 50 and his age (option C) is not a risk factor for now. He tends to tan rather than burn (option\nA) which is a protective factor. While childhood sunburns are a risk factor, their absence (option D) is not\none.","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"10bc2ae826caf7aef05ca924d591d1b1d983467e","duplicate_group_id":"exact-10bc2ae826ca","duplicate_sources":[{"record_id":"3ea012ef15a8e425b2c9","record_type":"text_mcq","source_file":"Dermatology amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Dermatology amedex 2025.pdf","source_page":49,"source_qid":null},{"record_id":"79e84943f9303b63645a","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":24,"source_qid":null},{"record_id":"51d10d87dfc5b455816f","record_type":"text_mcq","source_file":"AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 DERMATOLOGY 1-60.pdf","source_page":23,"source_qid":null},{"record_id":"79ba6426f30895972253","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":242,"source_qid":"1784"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
