INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9c05384a0919b536c084','Git amedex 2025.pdf','5','Gastroenterology','A 35-year-old woman presents with a 4-month history of dysphagia to both solid and liquid foods. A barium study is done
demonstrating dilated esophagus with tapering at the lower end. Based on the history and radiological findings, achalasia is
the diagnosis. Which one of the following is the most appropriate management for this patient?','{"A":"A. Pyloromyotomy.","B":"OB. Pneumatic dilation.","C":"C. Botulinum toxin injection.","D":"D. Calcium channel blockers.","E":"E. Nitrates."}','B','Achalasia is a primary esophageal motility disorder characterized by the absence of esophageal peristalsis and impaired
lower esophageal sphincter (LES) relaxation in response to swallowing. These abnormalities cause a functional obstruction at
the gastroesophageal junction.

The goal of treatment is to reduce the resistance of the LES and overcome the obstruction.

Currently, the standard of care for achalasia is based on guidelines from the American College of Gastroenterology and is
as follows:

¢ Initial therapy should be either graded pneumatic dilation (PD) or laparoscopic surgical myotomy in patients who are fit
for such surgeries.

¢ Botulinum toxin injection into the LES is considered for patients who are not appropriate candidates for surgery.

e Pharmacologic therapy can be used for patients not undergoing PD or myotomy and who have failed botulinum toxin
therapy (nitrates and calcium channel blockers most are common)

For this patient, either pneumatic dilation or endoscopic myotomy (not an option) is the most appropriate initial management
option.

(Option A) A pyloromyotomy is a procedure used for the treatment of hypertrophic pyloric stenosis or obstruction.

(Option C) Botulinum toxin injection is considered the next most appropriate treatment in patients with mild symptoms or
those who are not appropriate candidates for pneumatic balloon dilation or surgery. Botulinum toxin injection has been
associated with symptom improvement but may need to be repeated at 3-12 months intervals.

(Options D and E) Pharmacological therapy can be used for those patients not undergoing pneumatic dilation or myotomy,
and who have failed botulinum toxin therapy. These medications, however, may not be desirably effective. First-line medical
treatment is with glyceryl trinitrate (oral or sublingual spray). If the episodes are associated with spasms or are frequent or
disabling, a trial of diltiazem, nifedipine, or isosorbide dinitrate can be considered.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","supporting_pages":[5],"source_qid":null,"duplicate_group_id":"exact-0c82e629189a","duplicate_sources":[{"record_id":"9c05384a0919b536c084","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":5,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"9c05384a0919b536c084","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_year":2025,"source_page":5,"supporting_pages":[5],"source_qid":null,"domain_hint":"Gastroenterology","stem":"A 35-year-old woman presents with a 4-month history of dysphagia to both solid and liquid foods. A barium study is done\ndemonstrating dilated esophagus with tapering at the lower end. Based on the history and radiological findings, achalasia is\nthe diagnosis. Which one of the following is the most appropriate management for this patient?","options":{"A":"A. Pyloromyotomy.","B":"OB. Pneumatic dilation.","C":"C. Botulinum toxin injection.","D":"D. Calcium channel blockers.","E":"E. Nitrates."},"source_answer":"B","source_explanation":"Achalasia is a primary esophageal motility disorder characterized by the absence of esophageal peristalsis and impaired\nlower esophageal sphincter (LES) relaxation in response to swallowing. These abnormalities cause a functional obstruction at\nthe gastroesophageal junction.\n\nThe goal of treatment is to reduce the resistance of the LES and overcome the obstruction.\n\nCurrently, the standard of care for achalasia is based on guidelines from the American College of Gastroenterology and is\nas follows:\n\n¢ Initial therapy should be either graded pneumatic dilation (PD) or laparoscopic surgical myotomy in patients who are fit\nfor such surgeries.\n\n¢ Botulinum toxin injection into the LES is considered for patients who are not appropriate candidates for surgery.\n\ne Pharmacologic therapy can be used for patients not undergoing PD or myotomy and who have failed botulinum toxin\ntherapy (nitrates and calcium channel blockers most are common)\n\nFor this patient, either pneumatic dilation or endoscopic myotomy (not an option) is the most appropriate initial management\noption.\n\n(Option A) A pyloromyotomy is a procedure used for the treatment of hypertrophic pyloric stenosis or obstruction.\n\n(Option C) Botulinum toxin injection is considered the next most appropriate treatment in patients with mild symptoms or\nthose who are not appropriate candidates for pneumatic balloon dilation or surgery. Botulinum toxin injection has been\nassociated with symptom improvement but may need to be repeated at 3-12 months intervals.\n\n(Options D and E) Pharmacological therapy can be used for those patients not undergoing pneumatic dilation or myotomy,\nand who have failed botulinum toxin therapy. These medications, however, may not be desirably effective. First-line medical\ntreatment is with glyceryl trinitrate (oral or sublingual spray). If the episodes are associated with spasms or are frequent or\ndisabling, a trial of diltiazem, nifedipine, or isosorbide dinitrate can be considered.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","guideline","interval","management","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-stagi