INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('2d06f8f4c7beccdaaf1d','Git amedex 2025.pdf','13','Gastroenterology','Which one of the following is not correct regarding hemochromatosis?','{"A":"The incidence of hemochromatosis in Australia is 1:200.","B":"C282Y homozygous accounts for approximately 90% of\nhemochromatosis cases in Australia.","C":"The majority of patients with one copy of C282Y and H63D mutation\nnever develop hemochromatosis.","D":"OD. Ninety percent of those with homozygous C282Y will develop\nsymptoms at some stage of their lives.","E":"Carriers of only one copy of the mutated HFE gene will not be affected\nclinically."}','D','(Option A) Correct - The incidence of hereditary hemochromatosis (HH) in
Australia is 1 in 200-300.

(Option B) Correct - Approximately 80-90% of HH cases in Australia have
homozygous C282Y mutations of their HFE gene.

(Option C) Correct - Most patients with heterozygous C282Y/H63D mutations
never develop clinical symptoms or will have only mild symptoms.

(Option D) Incorrect—Only 28.4% of males and 1.2% of females with the
C282Y mutation will develop a clinically significant presentation of iron overload
at some point in their lives.

(Option E) Correct - Carriers of a gene mutation will never be symptomatic','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-c2ddedbfc899","duplicate_sources":[{"record_id":"2d06f8f4c7beccdaaf1d","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":13,"source_qid":null},{"record_id":"b5d6736f0b3a8d772955","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 76-100.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 76-100.pdf","source_page":46,"source_qid":null},{"record_id":"dbb31459609d2b31e9ab","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":486,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"2d06f8f4c7beccdaaf1d","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_year":2025,"source_page":13,"source_qid":null,"domain_hint":"Gastroenterology","stem":"Which one of the following is not correct regarding hemochromatosis?","options":{"A":"The incidence of hemochromatosis in Australia is 1:200.","B":"C282Y homozygous accounts for approximately 90% of\nhemochromatosis cases in Australia.","C":"The majority of patients with one copy of C282Y and H63D mutation\nnever develop hemochromatosis.","D":"OD. Ninety percent of those with homozygous C282Y will develop\nsymptoms at some stage of their lives.","E":"Carriers of only one copy of the mutated HFE gene will not be affected\nclinically."},"source_answer":"D","source_explanation":"(Option A) Correct - The incidence of heredita