rding in an\nill and toxic patient.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"69dbb8aa4f2e717ee21b171af90a62ff77863525","duplicate_group_id":"exact-69dbb8aa4f2e","duplicate_sources":[{"record_id":"abcbb5a14a13db27c910","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":25,"source_qid":null},{"record_id":"2a9e308d802f9ad23985","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 1-40.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 1-40.pdf","source_page":138,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
