INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7be552d51f5baf6ea0bc','Git amedex 2025.pdf','31','Gastroenterology','A 67-year-old man presents to your GP clinic with a complaint of fresh rectal bleeding covering
the outer surface of his stool for the past three weeks. He is otherwise in good health. Which one
of the following is the most appropriate next step in evaluation?','{"A":"OA. Digital rectal exam (DRE).","B":"B. Proctoscopy.","C":"C. Flexible sigmoidoscopy.","D":"D. Rigid sigmoidoscopy.","E":"E. Colonoscopy."}','A','Rectal bleeding is often caused by benign conditions such as hemorrhoids or anal fissures.
However, this assumption may mask serious and more proximal pathologies such as colorectal
cancer. To avoid missing patients with sinister conditions, either as the cause of bleeding or a
concomitant problem, all such patients should be assessed even if, based on the history, the
etiology is apparent.

The approach to patients with rectal bleeding starts with a thorough history followed by a physical
exam. The physical examination should be directed at identifying possible or definite sources of
bleeding and finding worrisome distal lesions that may be detectable. A detailed physical
examination must include an external inspection of the anus and a digital rectal exam as initial
investigations.

Having the patient bear down during the examination may induce prolapse of a hemorrhoid or
bleeding of a superficial lesion. Moreover, office-based anoscopy or proctoscopy (option B)
should be performed in patients with acute rectal bleeding when available. These are simple
measures that do not require bowel preparation.

Sigmoidoscopy (options C and D) or colonoscopy (option E) is indicated in patients whose
initial assessment suggests more proximal lesions as the cause.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","supporting_pages":[31],"source_qid":null,"duplicate_group_id":"exact-e90e819c36c9","duplicate_sources":[{"record_id":"7be552d51f5baf6ea0bc","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":31,"source_qid":null},{"record_id":"77eaeb8942b0e44e203f","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 41-75.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 41-75.pdf","source_page":22,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"7be552d51f5baf6ea0bc","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_year":2025,"source_page":31,"supporting_pages":[31],"source_qid":null,"domain_hint":"Gastroenterology","stem":"A 67-year-old man presents to your GP clinic with a complaint of fresh rectal bleeding covering\nthe outer surface of his stool for the past three weeks. He is otherwise in good health. Which one\nof the following is the most appropriate next step in evaluation?","options":{"A":"OA. Digital rectal exam (DRE).","B":"B. Proctoscopy.","C":"C. Flexible sigmoidoscopy.","D":"D. Rigid sigmoidoscopy.","E":"E. Colonoscopy."},"source_answer":"A","source_explanation":"Rectal bleeding is often caused by benign conditions such as hemorrhoids or anal fissures.\nHowever, this assumption may mask serious and more proximal pathologies such as colorectal\ncancer. To avoid missing patients with sinister conditions, either as the cause of bleeding or a\nconcomitant problem, all such patients should be assessed even if, based on the history, the\netiology is apparent.\n\nThe approach to patients with rectal bleeding starts with a thorough history followed by a physical\nexam. The physical examination should be directed at identifying possible or definite sources of\nbleeding and finding worrisome distal lesions that may be detectable. A detailed physical\nexamination must include an external inspection of the anus and a digital rectal exam as initial\ninvestigations.\n\nHaving the patient bear down during the examination may induce prolapse of a hemorrhoid or\nbleeding of a superficial lesion. Moreover, office-based anoscopy or proctoscopy (option B)\nshould be performed in patients with acute rectal bleeding when available. These are simple\nmeasures that do not require bowel preparation.\n\nSigmoidoscopy (options C and D) or colonoscopy (option E) is indicated in patients whose\ninitial assessment suggests more proximal lesions as the cause.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"e90e819c36c9bdf62b908d29a146321661c0270f","duplicate_group_id":"exact-e90e819c36c9","duplicate_sources":[{"record_id":"7be552d51f5baf6ea0bc","record_type":"text_mcq","source_file":"Git amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Git amedex 2025.pdf","source_page":31,"source_qid":null},{"record_id":"77eaeb8942b0e44e203f","record_type":"text_mcq","source_file":"AMEDEX 2025 GIT 41-75.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GIT 41-75.pdf","source_page":22,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
